 13	/**
 14	 * Who a payment record belongs to when our metadata didn't say: the Stripe
 15	 * customer id on the account, else the PaymentIntent's Checkout Session (whose
 16	 * metadata carries nxeonUserId), else the PaymentIntent itself. Best-effort.
 17	 */
 18	const resolveUser: UserResolver = async (m) => {
 19	  if (m.stripeCustomer) {
 20	    const u = await db.user.findFirst({ where: { stripeCustomerId: m.stripeCustomer }, select: { id: true } });
 21	    if (u) return u.id;
 22	  }
 23	  if (m.paymentIntentId) {
 24	    const sessions = await stripe().checkout.sessions.list({ payment_intent: m.paymentIntentId, limit: 1 });
 25	    const uid = sessions.data[0]?.metadata?.nxeonUserId;
 26	    if (uid) return uid;
 27	    const pi = await stripe().paymentIntents.retrieve(m.paymentIntentId);
 28	    if (pi.metadata?.nxeonUserId) return pi.metadata.nxeonUserId;
 29	    const cust = typeof pi.customer === "string" ? pi.customer : pi.customer?.id;
 30	    if (cust) {
 31	      const u = await db.user.findFirst({ where: { stripeCustomerId: cust }, select: { id: true } });
 32	      if (u) return u.id;
 33	    }
 34	  }
 35	  return null;
 36	};
