 38	/** URGENT in-app alert to every admin when a customer opens a dispute (no email). */
 39	async function alertDispute(d: Stripe.Dispute): Promise<void> {
 40	  const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
 41	  if (!admins.length) return;
 42	  const due = d.evidence_details?.due_by ? new Date(d.evidence_details.due_by * 1000).toISOString().slice(0, 10) : "see Stripe";
 43	  await db.notification.createMany({
 44	    data: admins.map((a) => ({
 45	      userId: a.id,
 46	      title: `URGENT: card dispute opened (${(d.amount / 100).toFixed(2)} ${d.currency.toUpperCase()})`,
 47	      body: `Reason: ${String(d.reason).replace(/_/g, " ")}. Evidence due ${due}. Dispute ${d.id} — respond in the Stripe dashboard.`,
 48	      href: "/admin/billing",
 49	    })),
 50	  });
 51	}
