 53	export async function POST(req: NextRequest) {
 54	  if (!stripeConfigured() || !process.env.STRIPE_WEBHOOK_SECRET) {
 55	    return NextResponse.json({ error: "not configured" }, { status: 400 });
 56	  }
 57	  const sig = req.headers.get("stripe-signature");
 58	  if (!sig) return NextResponse.json({ error: "missing signature" }, { status: 400 });
 59	  const raw = await req.text();
 60	
 61	  let event;
 62	  try {
 63	    event = stripe().webhooks.constructEvent(raw, sig, process.env.STRIPE_WEBHOOK_SECRET);
 64	  } catch {
 65	    return NextResponse.json({ error: "invalid signature" }, { status: 400 });
 66	  }
 67	
 68	  // `async_payment_succeeded` is how a DELAYED local payment method (PayNow,
 69	  // GrabPay, UPI, ...) reports that the money finally arrived: its
 70	  // `checkout.session.completed` can fire while the session is still unpaid, which
 71	  // fulfilCheckoutSession correctly treats as "not yet". Same idempotent call.
 72	  // (Owner action: enable this event on the Stripe webhook endpoint before turning
 73	  // any local method on — see docs/DOCUMENTATION.md, Local payment methods.)
 74	  if (event.type === "checkout.session.completed" || event.type === "checkout.session.async_payment_succeeded") {
 75	    const session = event.data.object as { id: string };
 76	    // FULFIL, don't just credit. This used to call `creditCheckoutSession` and
 77	    // throw the result away, which meant the webhook credited the wallet and then
 78	    // — by winning the race — caused the success-redirect to see `credited: false`
 79	    // and skip provisioning entirely. The webhook is the reliable signal (the
 80	    // redirect may never happen at all), so it must be able to fulfil on its own.
 81	    // `fulfilCheckoutSession` is idempotent via UNIQUE(FulfilledSession), so the
 82	    // two callers racing is safe: exactly one does the work.
 83	    //
 84	    // Errors are swallowed deliberately — returning non-2xx makes Stripe retry the
 85	    // event, and the failure is already recorded on the FulfilledSession row and
 86	    // surfaced to the customer.
 87	    try {
 88	      await fulfilCheckoutSession(session.id);
 89	    } catch (e) {
 90	      console.error("[stripe-webhook] fulfil failed", session.id, e);
 91	    }
 92	  }
 93	
 94	  // A checkout the customer never completed: Stripe expires it (we cap the payable
 95	  // window at ORDER_CHECKOUT_EXPIRES_MS). RELEASE any first-month-free hold it carried
 96	  // so the customer's one-time offer is returned promptly rather than waiting for the
 97	  // worker sweep. Guarded to RESERVED, so a completed+confirmed grant is never revoked.
 98	  // (If this event type isn't enabled in the Stripe dashboard, the worker sweep is the
 99	  // backstop — the hold's reservedUntil has passed by the time the session expires.)
100	  // A DELAYED local method (PayNow, GrabPay, UPI, ...) that the bank finally refused: the session is
101	  // complete but will never be paid, so it never expires either. Same release as an expiry — the
102	  // order was never placed (fulfilment only runs on `paid`), only the holds are returned.
103	  if (event.type === "checkout.session.expired" || event.type === "checkout.session.async_payment_failed") {
104	    const session = event.data.object as Stripe.Checkout.Session;
105	    const token = session.metadata?.nxeonPromoReservation;
106	    if (token) {
107	      try {
108	        await releaseReservation(token);
109	      } catch (e) {
110	        console.error("[stripe-webhook] release reservation failed", token, e);
111	      }
112	    }
113	    // Same for a checkout-coupon hold — return its per-person slot AND its global-cap
114	    // slot (timesRedeemed decrement inside releaseOrderCouponReservation). Guarded to
115	    // RESERVED, so a completed+confirmed CONSUMED redemption is never revoked.
116	    const couponToken = session.metadata?.nxeonCouponReservation;
117	    if (couponToken) {
118	      try {
119	        await releaseOrderCouponReservation(couponToken);
120	      } catch (e) {
121	        console.error("[stripe-webhook] release coupon reservation failed", couponToken, e);
122	      }
123	    }
124	  }
125	
126	  // A payment attempt failed. Filtered inside handleFailedPaymentIntent to only
127	  // act on the 3D Secure / authentication-stalled case — ordinary declines are
128	  // already shown to the customer inline by Stripe's own checkout UI. Errors
129	  // swallowed deliberately: a recovery-email hiccup must never surface as a
130	  // webhook failure Stripe would retry indefinitely.
131	  if (event.type === "payment_intent.payment_failed") {
132	    const pi = event.data.object as Stripe.PaymentIntent;
133	    try {
134	      await handleFailedPaymentIntent(pi);
135	    } catch (e) {
136	      console.error("[stripe-webhook] failed-payment recovery failed", pi.id, e);
137	    }
138	  }
139	
140	  // Cyrus token plans/top-ups (lib/cyrus/tokens/billing.ts): grants keyed by invoice /
141	  // session id, so redeliveries are no-ops. Their sessions carry `cyrusUserId`, never
142	  // `nxeonUserId`, so fulfilCheckoutSession above classifies them "unpaid" and skips them.
143	  // Swallowed like the rest: the worker's reconcile sweep re-applies anything missed.
144	  try {
145	    await handleCyrusStripeEvent(event);
146	  } catch (e) {
147	    console.error("[stripe-webhook] cyrus tokens failed", event.id, e);
148	  }
149	
150	  // Payment record for the customer timeline (lib/payment-events.ts). Idempotent on
151	  // the event id, so Stripe's redeliveries never double-log. Never fails the webhook.
152	  try {
153	    const r = await recordStripeEvent(event, resolveUser);
154	    if (event.type === "charge.dispute.created" && r === "created") {
155	      await alertDispute(event.data.object as Stripe.Dispute).catch((e) => console.error("[stripe-webhook] dispute alert failed", e));
156	    }
157	    // A refund made in the Stripe dashboard (not our admin Refund control) updates nothing
158	    // of ours — flag it to admins, warn about auto-renew, and email the customer.
159	    // `r === "created"` = first delivery; the handler is also idempotent on the refund id.
160	    if (event.type === "charge.refunded" && r === "created") {
161	      await handleExternalRefund(event.data.object as Stripe.Charge, (a) =>
162	        resolveUser(a as unknown as Parameters<UserResolver>[0]),
163	      ).catch((e) => console.error("[stripe-webhook] external refund handling failed", event.id, e));
164	    }
165	  } catch (e) {
166	    console.error("[stripe-webhook] payment record failed", event.id, e);
167	  }
168	
169	  return NextResponse.json({ received: true });
170	}

1	     1	// Cyrus plans + top-ups on Stripe. Server only; plain module (webhook, routes, worker).
2	     2	//
3	     3	// Plans are real Stripe Billing subscriptions (monthly). Every PAID plan invoice grants
4	     4	// that month's tokens, keyed by the invoice id (`plan:<invoiceId>`), so tokens stack on
5	     5	// each renewal and a webhook redelivery, the return redirect and the reconcile sweep can
6	     6	// all run the same grant without double-granting. Top-ups are one-off Checkout payments
7	     7	// keyed by the session id (`topup:<sessionId>`).
8	     8	//
9	     9	// ISOLATION FROM THE WALLET: our Checkout Sessions carry `cyrusUserId`, NEVER
10	    10	// `nxeonUserId`. lib/fulfil-checkout.ts classifies a session without `nxeonUserId` as
11	    11	// "unpaid" and does nothing, so the platform's wallet/order fulfilment can never mistake
12	    12	// a Cyrus purchase for a wallet top-up (test/cyrus-tokens-stripe.test.ts pins this).
13	    13	import type Stripe from "stripe";
14	    14	import type { User } from "@prisma/client";
15	    15	import { cyrusDb as db } from "../db";
16	    16	import { loadTokenConfig, PLAN_TIERS, type PlanTier, type TokenConfig } from "./config";
17	    17	import { PLAN_LOOKUP_KEY, planInvoiceTokens, tierFromLookupKey, TIER_RANK, topupTokens, validTopupCents, fmt } from "./economy";
18	    18	import { capLotExpiry, creditTokens, revokeTokens } from "./ledger";
19	    19	import { lapseExpiry, planActive, planGrantExpiry, rolloverRoom } from "./rollover";
20	    20	import { getHost } from "../host";
21	    21	import { cardTopupEnvelope, deliverPurchase, reconcileCardTopups, reconcileWalletTopups, walletPayEnabled } from "./purchase";
22	    22	
23	    23	const DAY = 86_400_000;
24	    24	// Stripe is the host's (host.billing.stripe; inside Nxeon it is lib/stripe + lib/stripe-cards, unchanged). null = no payments.
25	    25	const hostStripe = () => getHost().billing.stripe;
26	    26	const stripe = (): Stripe => { const h = hostStripe(); if (!h) throw new Error("Stripe is not configured"); return h.client(); };
27	    27	const stripeConfigured = () => !!hostStripe()?.configured();
28	    28	const stripePublishableKey = () => hostStripe()?.publishableKey() ?? "";
29	    29	const createCheckoutSessionLogged = (params: Stripe.Checkout.SessionCreateParams, options?: Stripe.RequestOptions) => {
30	    30	  const h = hostStripe();
31	    31	  if (!h) throw new Error("Stripe is not configured");
32	    32	  return h.createCheckoutSession(params, options);
33	    33	};
34	    34	const uiMode = () => hostStripe()?.uiMode;
35	    35	const requestOpts = () => hostStripe()?.requestOptions;
