37	    37	type StripeLike = Stripe;
38	    38	let override: StripeLike | null = null;
39	    39	/** Tests inject a fake client (no network). */
40	    40	export function setCyrusStripeForTests(s: StripeLike | null) { override = s; priceCache = null; }
41	    41	const sc = (): StripeLike => override ?? stripe();
42	    42	const configured = () => !!override || stripeConfigured();
43	    43	const appBase = () => process.env.APP_URL ?? "http://localhost:3000";
44	    44	const ts = (n: number | null | undefined) => (n ? new Date(n * 1000) : null);
45	    45	const idOf = (x: string | { id: string } | null | undefined) => (typeof x === "string" ? x : x?.id ?? null);
