51	    51	export type PlanPrice = { tier: PlanTier; id: string; unitAmount: number | null; currency: string; livemode: boolean };
52	    52	let priceCache: { at: number; key: string; prices: Record<PlanTier, PlanPrice | null> } | null = null;
53	    53	
54	    54	/** The three plan prices: Setting override ids, else the price with lookup_key cyrus_plan_<tier>_v1. */
55	    55	export async function planPrices(cfg?: TokenConfig): Promise<Record<PlanTier, PlanPrice | null>> {
56	    56	  const c = cfg ?? (await loadTokenConfig());
57	    57	  const empty = { katara: null, saka: null, all: null } as Record<PlanTier, PlanPrice | null>;
58	    58	  if (!configured()) return empty;
59	    59	  const key = JSON.stringify(c.plan.priceIds);
60	    60	  if (priceCache && priceCache.key === key && Date.now() - priceCache.at < 10 * 60_000) return priceCache.prices;
61	    61	  const out = { ...empty };
62	    62	  const toPlan = (tier: PlanTier, p: Stripe.Price): PlanPrice => ({ tier, id: p.id, unitAmount: p.unit_amount, currency: p.currency, livemode: p.livemode });
63	    63	  try {
64	    64	    const listed = await sc().prices.list({ lookup_keys: PLAN_TIERS.map(PLAN_LOOKUP_KEY), active: true, limit: 10 });
65	    65	    for (const p of listed.data) { const t = tierFromLookupKey(p.lookup_key); if (t && !out[t]) out[t] = toPlan(t, p); }
66	    66	    for (const t of PLAN_TIERS) {
67	    67	      const id = c.plan.priceIds[t];
68	    68	      if (id) out[t] = toPlan(t, await sc().prices.retrieve(id));
69	    69	    }
70	    70	  } catch (e) {
71	    71	    console.error("[cyrus-tokens] price lookup failed", (e as Error).message);
72	    72	    return empty;
73	    73	  }
74	    74	  priceCache = { at: Date.now(), key, prices: out };
75	    75	  return out;
76	    76	}
77	    77	
78	    78	export async function tierOfPrice(price: string | Stripe.Price | null | undefined, cfg?: TokenConfig): Promise<PlanTier | null> {
79	    79	  if (!price) return null;
80	    80	  if (typeof price !== "string") {
81	    81	    const t = tierFromLookupKey(price.lookup_key) ?? (price.metadata?.cyrus_tier as PlanTier | undefined);
82	    82	    if (t && (PLAN_TIERS as readonly string[]).includes(t)) return t as PlanTier;
83	    83	  }
84	    84	  const id = idOf(price);
85	    85	  const prices = await planPrices(cfg);
86	    86	  return PLAN_TIERS.find((t) => prices[t]?.id === id) ?? null;
87	    87	}
