95	    95	const ACTIVE = ["active", "trialing", "past_due", "incomplete"];
96	    96	
97	    97	async function customerFor(user: User): Promise<string> {
98	    98	  if (override) {
99	    99	    if (user.stripeCustomerId) return user.stripeCustomerId;
100	   100	    const c = await sc().customers.create({ email: user.email, metadata: { nxeonUserId: user.id } });
101	   101	    await getHost().users.setBillingCustomerId(user.id, c.id);
102	   102	    return c.id;
103	   103	  }
104	   104	  const h = hostStripe();
105	   105	  if (!h) throw new Error("Stripe is not configured");
106	   106	  return h.ensureCustomer(user);
107	   107	}
