109	   109	export async function openPlanCheckout(user: User, tier: PlanTier, opts: { returnBase?: string } = {}): Promise<CheckoutOpen> {
110	   110	  if (!configured()) return { ok: false, error: "Payments aren't available right now." };
111	   111	  const cfg = await loadTokenConfig();
112	   112	  const price = (await planPrices(cfg))[tier];
113	   113	  if (!price) return { ok: false, error: "Plans aren't set up yet. Please try again later." };
114	   114	  const cur = await db.cyrusPlan.findUnique({ where: { userId: user.id } });
115	   115	  if (cur && ACTIVE.includes(cur.status) && !cur.endedAt) return { ok: false, error: "You already have a plan. Change it from your plan instead." };
116	   116	  const customer = await customerFor(user);
117	   117	  const session = await (override ? sc().checkout.sessions.create.bind(sc().checkout.sessions) : createCheckoutSessionLogged)({
118	   118	    mode: "subscription",
119	   119	    customer,
120	   120	    ui_mode: uiMode(),
121	   121	    payment_method_types: ["card"],
122	   122	    line_items: [{ price: price.id, quantity: 1 }],
123	   123	    return_url: `${opts.returnBase ?? appBase()}/api/cyrus/tokens/return?session_id={CHECKOUT_SESSION_ID}`,
124	   124	    metadata: { cyrusUserId: user.id, cyrusKind: "plan", cyrusTier: tier },
125	   125	    subscription_data: { metadata: { cyrusUserId: user.id, cyrusTier: tier }, description: `Cyrus ${tier === "all" ? "All models" : tier[0].toUpperCase() + tier.slice(1)} plan` },
126	   126	  }, requestOpts());
127	   127	  return session.client_secret ? { ok: true, clientSecret: session.client_secret, publishableKey: stripePublishableKey() } : { ok: false, error: "Couldn't open checkout." };
128	   128	}
