130	   130	export async function openTopupCheckout(user: User, cents: number, opts: { returnBase?: string } = {}): Promise<CheckoutOpen> {
131	   131	  if (!configured()) return { ok: false, error: "Payments aren't available right now." };
132	   132	  const cfg = await loadTokenConfig();
133	   133	  if (!cfg.topup.enabled) return { ok: false, error: "Top-ups aren't available right now." };
134	   134	  if (!validTopupCents(cents, cfg)) return { ok: false, error: `Pick an amount from $${(cfg.topup.minCents / 100).toFixed(0)} to $${(cfg.topup.maxCents / 100).toFixed(0)}.` };
135	   135	  if (cfg.topup.requiresPaid) {
136	   136	    const paid = await getHost().servers.paidCount(user.id) + await db.cyrusPlan.count({ where: { userId: user.id } });
137	   137	    if (!paid) return { ok: false, error: "Top-ups are for customers with a game server or a Cyrus plan." };
138	   138	  }
139	   139	  const tokens = topupTokens(cents, cfg);
140	   140	  const customer = await customerFor(user);
141	   141	  const md = { cyrusUserId: user.id, cyrusKind: "topup", cyrusTokens: String(tokens), cyrusCents: String(cents) };
142	   142	  const session = await (override ? sc().checkout.sessions.create.bind(sc().checkout.sessions) : createCheckoutSessionLogged)({
143	   143	    mode: "payment",
144	   144	    customer,
145	   145	    ui_mode: uiMode(),
146	   146	    payment_method_types: ["card"],
147	   147	    line_items: [{ price_data: { currency: "usd", unit_amount: cents, product_data: { name: `${fmt(tokens)} Cyrus tokens` } }, quantity: 1 }],
148	   148	    return_url: `${opts.returnBase ?? appBase()}/api/cyrus/tokens/return?session_id={CHECKOUT_SESSION_ID}`,
149	   149	    metadata: md,
150	   150	    payment_intent_data: { metadata: md, description: `${fmt(tokens)} Cyrus tokens` },
151	   151	  }, requestOpts());
152	   152	  return session.client_secret ? { ok: true, clientSecret: session.client_secret, publishableKey: stripePublishableKey() } : { ok: false, error: "Couldn't open checkout." };
153	   153	}
