155	   155	/** A paid top-up session -> tokens (idempotent per session). Returns tokens granted (0 if replay/unpaid). */
156	   156	export async function fulfilTopup(session: Stripe.Checkout.Session): Promise<number> {
157	   157	  const md = session.metadata ?? {};
158	   158	  if (md.cyrusKind !== "topup" || !md.cyrusUserId || session.payment_status !== "paid" || session.mode !== "payment") return 0;
159	   159	  const cfg = await loadTokenConfig();
160	   160	  const paidCents = session.amount_total ?? 0;
161	   161	  // The amount actually paid decides the tokens; the metadata figure is only a cap.
162	   162	  const tokens = Math.min(Number(md.cyrusTokens) || 0, topupTokens(paidCents, cfg));
163	   163	  // r44: through the purchase path (direct credit, or the signed webhook/outbox when CYRUS_PURCHASE_EVENTS=1), same
164	   164	  // idemKey as before, so a return-leg + webhook race or a redelivery still credits exactly once
165	   165	  const r = await deliverPurchase(topupSessionEnvelope(session, md.cyrusUserId, tokens, paidCents, cfg));
166	   166	  return r.tokens;
167	   167	}
