169	   169	/** The purchase envelope of a paid top-up session (also used by the reconcile sweep). */
170	   170	export function topupSessionEnvelope(session: Stripe.Checkout.Session, userId: string, tokens: number, paidCents: number, cfg: { topup: { expiryDays: number } }) {
171	   171	  const at = session.created ? new Date(session.created * 1000) : new Date();
172	   172	  return cardTopupEnvelope({
173	   173	    userId, sessionId: session.id, tokens, paidCents, expiresAt: new Date(Date.now() + cfg.topup.expiryDays * DAY),
174	   174	    paymentIntent: idOf(session.payment_intent as string | { id: string } | null), livemode: session.livemode,
175	   175	  }, at);
176	   176	}
177	   177	
178	   178	/** r44: recent paid Cyrus top-up sessions whose event never landed get credited directly (CYRUS_PURCHASE_EVENTS only). */
179	   179	export async function reconcileCardTopupSessions(sinceMs = Date.now() - 3 * DAY): Promise<{ checked: number; credited: number }> {
180	   180	  if (process.env.CYRUS_PURCHASE_EVENTS !== "1" || !configured()) return { checked: 0, credited: 0 };
181	   181	  const cfg = await loadTokenConfig();
182	   182	  const list = await sc().checkout.sessions.list({ created: { gte: Math.floor(sinceMs / 1000) }, limit: 100 });
183	   183	  const envs = list.data.filter((x) => x.metadata?.cyrusKind === "topup" && x.metadata?.cyrusUserId && x.payment_status === "paid" && x.mode === "payment")
184	   184	    .map((x) => topupSessionEnvelope(x, x.metadata!.cyrusUserId!, Math.min(Number(x.metadata!.cyrusTokens) || 0, topupTokens(x.amount_total ?? 0, cfg)), x.amount_total ?? 0, cfg));
185	   185	  return reconcileCardTopups(envs);
186	   186	}
