188	   188	/** The Checkout return leg (and the webhook's checkout events). */
189	   189	export async function fulfilCyrusSession(sessionOrId: string | Stripe.Checkout.Session): Promise<{ kind: "plan" | "topup" | "none"; userId: string | null; tokens: number }> {
190	   190	  const session = typeof sessionOrId === "string" ? await sc().checkout.sessions.retrieve(sessionOrId) : sessionOrId;
191	   191	  const md = session.metadata ?? {};
192	   192	  if (!md.cyrusUserId) return { kind: "none", userId: null, tokens: 0 };
193	   193	  if (md.cyrusKind === "topup") return { kind: "topup", userId: md.cyrusUserId, tokens: await fulfilTopup(session) };
194	   194	  if (md.cyrusKind === "plan" && session.subscription) {
195	   195	    const before = await db.cyrusTokenLedger.aggregate({ where: { userId: md.cyrusUserId, source: "plan", kind: "purchase" }, _sum: { delta: true } });
196	   196	    await reconcileSubscription(idOf(session.subscription as string | { id: string })!);
197	   197	    const after = await db.cyrusTokenLedger.aggregate({ where: { userId: md.cyrusUserId, source: "plan", kind: "purchase" }, _sum: { delta: true } });
198	   198	    return { kind: "plan", userId: md.cyrusUserId, tokens: (after._sum.delta ?? 0) - (before._sum.delta ?? 0) };
199	   199	  }
200	   200	  return { kind: "none", userId: md.cyrusUserId, tokens: 0 };
201	   201	}
