212	   212	  const it = sub.items?.data?.[0] as (Stripe.SubscriptionItem & { current_period_start?: number; current_period_end?: number }) | undefined;
213	   213	  const legacy = sub as unknown as { current_period_start?: number; current_period_end?: number };
