217	   217	/** Mirror a Cyrus subscription into CyrusPlan. Returns the row (null if not ours). */
218	   218	export async function syncSubscription(sub: Stripe.Subscription): Promise<{ userId: string } | null> {
219	   219	  const userId = subUserId(sub);
220	   220	  if (!userId) return null;
221	   221	  const cfg = await loadTokenConfig();
222	   222	  const priceTier = (await tierOfPrice(sub.items?.data?.[0]?.price, cfg)) ?? (sub.metadata?.cyrusTier as PlanTier) ?? "katara";
223	   223	  const { start, end } = subPeriod(sub);
224	   224	  const cur = await db.cyrusPlan.findUnique({ where: { userId } });
225	   225	  const sameSub = cur?.stripeSubscriptionId === sub.id;
226	   226	  // A newer subscription replaces an old ended one; an old subscription's late event never
227	   227	  // overwrites a newer live one.
228	   228	  if (cur && !sameSub && ACTIVE.includes(cur.status) && !cur.endedAt && !ACTIVE.includes(sub.status)) return { userId };
229	   229	  const endedAt = ts(sub.ended_at);
230	   230	  const data = {
231	   231	    stripeCustomerId: idOf(sub.customer as string | { id: string })!,
232	   232	    stripeSubscriptionId: sub.id,
233	   233	    priceTier,
234	   234	    status: sub.status,
235	   235	    currentPeriodStart: start,
236	   236	    currentPeriodEnd: end,
237	   237	    cancelAtPeriodEnd: !!sub.cancel_at_period_end,
238	   238	    endedAt,
239	   239	    livemode: sub.livemode,
240	   240	    lastSyncAt: new Date(),
241	   241	  };
242	   242	  // `tier` (the paid entitlement) only ever comes from a paid invoice; a brand-new row
243	   243	  // starts at the price's tier but has no period until the first invoice is paid.
244	   244	  await db.cyrusPlan.upsert({
245	   245	    where: { userId },
246	   246	    create: { userId, tier: priceTier, ...data },
247	   247	    update: sameSub ? data : { tier: priceTier, ...data },
248	   248	  });
249	   249	  if (sub.status === "canceled" || sub.status === "incomplete_expired" || endedAt) {
250	   250	    // r41 lapse rule (lib/cyrus/tokens/rollover.ts): the plan's tokens expire at the period end or after the grace;
251	   251	    // under freeze_then_expire they are also not spendable meanwhile (the ledger checks the plan row).
252	   252	    await capLotExpiry(userId, "plan", lapseExpiry(end ?? endedAt ?? new Date(), cfg));
253	   253	  } else if (cfg.plan.rolloverMode === "while_active" && planActive({ status: sub.status, endedAt: null, currentPeriodEnd: end }, cfg, new Date())) {
254	   254	    // active again (or still): rolled-over plan tokens that a lapse had put on a clock keep rolling, unexpired ones only
255	   255	    await db.cyrusTokenLot.updateMany({ where: { userId, source: "plan", remaining: { gt: 0 }, expiresAt: { gt: new Date() } }, data: { expiresAt: null } });
256	   256	  }
257	   257	  // r38: Nxeon -> Cyrus entitlement event (host hook absent, or CYRUS_PLATFORM_EVENTS off = nothing)
258	   258	  void getHost().billing.entitlementChanged?.(userId)?.catch(() => undefined);
259	   259	  return { userId };
260	   260	}
