265	   265	  return (inv.lines?.data ?? []).map((l) => {
266	   266	    const anyL = l as unknown as { pricing?: { price_details?: { price?: string | Stripe.Price } }; price?: Stripe.Price; proration?: boolean; parent?: { subscription_item_details?: { proration?: boolean } } };
267	   267	    return {
268	   268	      amount: l.amount,
269	   269	      price: anyL.pricing?.price_details?.price ?? anyL.price ?? null,
270	   270	      periodEnd: ts(l.period?.end),
271	   271	      proration: !!(anyL.proration ?? anyL.parent?.subscription_item_details?.proration),
272	   272	    };
273	   273	  });
274	   274	}
