277	   277	  const p = (inv as unknown as { parent?: { subscription_details?: { subscription?: string | { id: string } } }; subscription?: string | { id: string } });
278	   278	  return idOf(p.parent?.subscription_details?.subscription ?? p.subscription ?? null);
279	   279	}
