287	   287	  const p = (inv as unknown as { payments?: { data?: { payment?: { payment_intent?: string | { id: string } } }[] }; payment_intent?: string | { id: string } });
288	   288	  const direct = idOf(p.payments?.data?.[0]?.payment?.payment_intent ?? p.payment_intent ?? null);
289	   289	  if (direct) return direct;
290	   290	  try {
291	   291	    const list = await (sc() as unknown as { invoicePayments: { list: (q: { invoice: string; limit: number }) => Promise<{ data: { payment?: { payment_intent?: string | { id: string } } }[] }> } }).invoicePayments.list({ invoice: inv.id!, limit: 3 });
