296	   296	/**
297	   297	 * Grant the tokens of one PAID Cyrus plan invoice (idempotent per invoice) and move the
298	   298	 * paid entitlement to the invoice's tier. Returns tokens newly granted.
299	   299	 */
300	   300	export async function grantPlanInvoice(inv: Stripe.Invoice, userIdHint?: string | null): Promise<number> {
301	   301	  if (inv.status !== "paid" || !inv.id) return 0;
302	   302	  const subId = invoiceSubscriptionId(inv);
303	   303	  const plan = subId ? await db.cyrusPlan.findUnique({ where: { stripeSubscriptionId: subId } }) : null;
304	   304	  const userId = invoiceMetaUser(inv) ?? plan?.userId ?? userIdHint ?? null;
305	   305	  if (!userId) return 0;
306	   306	  const cfg = await loadTokenConfig();
307	   307	  const lines = invoiceLines(inv);
308	   308	  let tier: PlanTier | null = null;
309	   309	  let periodEnd: Date | null = null;
310	   310	  for (const l of lines) {
311	   311	    if (l.amount <= 0) continue;
312	   312	    const t = await tierOfPrice(l.price, cfg);
313	   313	    if (t && (!tier || TIER_RANK[t] > TIER_RANK[tier])) { tier = t; periodEnd = l.periodEnd; }
314	   314	  }
315	   315	  if (!tier) return 0;
316	   316	  const priceCents = (await planPrices(cfg))[tier]?.unitAmount ?? null;
317	   317	  const tokens = planInvoiceTokens({ billingReason: inv.billing_reason ?? null, amountPaidCents: inv.amount_paid, tier, priceCents }, cfg);
318	   318	  const pi = await invoicePaymentIntent(inv);
319	   319	  const now = new Date();
320	   320	  // r41: an invoice for a plan that already ended (late event) gets the lapse clock, not "rolls over while active"
321	   321	  const expiresAt = plan?.endedAt ? lapseExpiry(plan.currentPeriodEnd ?? plan.endedAt, cfg) : planGrantExpiry(now, cfg);
322	   322	  const r = await creditTokens({
323	   323	    userId,
324	   324	    amount: tokens,
325	   325	    kind: "purchase",
326	   326	    source: "plan",
327	   327	    sourceRef: inv.id,
328	   328	    idemKey: `plan:${inv.id}`,
329	   329	    // r41 rollover (rollover.ts): while_active = no expiry while the plan stays active; age = each month lasts
330	   330	    // `rolloverMonths`. The optional cap never takes tokens already held (no replay hazard): it only limits
331	   331	    // how much of a NEW month is credited, under the account lock.
332	   332	    expiresAt,
333	   333	    now,
334	   334	    clamp: async (tx, amount, at) => {
335	   335	      const held = await tx.cyrusTokenLot.aggregate({ where: { userId, source: "plan", remaining: { gt: 0 }, OR: [{ expiresAt: null }, { expiresAt: { gt: at } }] }, _sum: { remaining: true } });
336	   336	      const room = rolloverRoom(held._sum.remaining ?? 0, cfg.plan.tokens[tier!], cfg);
337	   337	      return amount > room ? { amount: room, note: `rollover cap: ${cfg.plan.rolloverCapMonths} months of plan tokens` } : { amount };
338	   338	    },
339	   339	    note: `${tier === "all" ? "All models" : tier[0].toUpperCase() + tier.slice(1)} plan · ${inv.billing_reason === "subscription_cycle" ? "renewal" : inv.billing_reason === "subscription_update" ? "upgrade" : "first month"}`,
340	   340	    meta: { invoice: inv.id, billingReason: inv.billing_reason ?? null, amountPaid: inv.amount_paid, tier, paymentIntent: pi, subscription: subId, livemode: inv.livemode },
341	   341	  });
342	   342	  // Entitlement follows the money: the tier of the latest paid invoice.
343	   343	  // An upgrade's proration invoice can only raise it; a cycle invoice sets it (a downgrade lands here).
344	   344	  if (plan) {
345	   345	    const isUpdate = inv.billing_reason === "subscription_update";
346	   346	    const data: { tier?: PlanTier; currentPeriodEnd?: Date } = {};
347	   347	    if (!isUpdate || TIER_RANK[tier] > TIER_RANK[(plan.tier as PlanTier) ?? "katara"]) data.tier = tier;
348	   348	    if (!isUpdate && periodEnd && (!plan.currentPeriodEnd || periodEnd > plan.currentPeriodEnd)) data.currentPeriodEnd = periodEnd;
349	   349	    if (Object.keys(data).length) await db.cyrusPlan.update({ where: { userId: plan.userId }, data });
350	   350	  }
351	   351	  return r.created ? r.amount : 0;
352	   352	}
