354	   354	/** Pull a subscription and its paid invoices from Stripe and apply everything missing. */
355	   355	export async function reconcileSubscription(subId: string): Promise<{ userId: string | null; granted: number }> {
356	   356	  const sub = await sc().subscriptions.retrieve(subId, { expand: ["items.data.price"] });
357	   357	  const s = await syncSubscription(sub);
358	   358	  if (!s) return { userId: null, granted: 0 };
359	   359	  // Line prices come back as ids; tierOfPrice maps them through the lookup-key price table.
360	   360	  const invs = await sc().invoices.list({ subscription: subId, status: "paid", limit: 24 });
361	   361	  let granted = 0;
362	   362	  for (const inv of [...invs.data].reverse()) granted += await grantPlanInvoice(inv, s.userId);
363	   363	  // grantPlanInvoice can move `tier`; re-sync status/period last.
364	   364	  await syncSubscription(await sc().subscriptions.retrieve(subId, { expand: ["items.data.price"] }));
365	   365	  return { userId: s.userId, granted };
366	   366	}
