368	   368	/** Reconcile one account's plan if it hasn't been synced recently (page loads call this). */
369	   369	export async function maybeReconcileUser(userId: string, maxAgeMs = 5 * 60_000): Promise<void> {
370	   370	  // Wallet top-ups (CYRUS_WALLET_PAY): a charge whose credit was lost is credited here (no-op when the flag is off).
371	   371	  if (walletPayEnabled()) await reconcileWalletTopups({ userId }).catch((e) => console.error("[cyrus-purchase] reconcile", userId, (e as Error).message));
372	   372	  if (!configured()) return;
373	   373	  const p = await db.cyrusPlan.findUnique({ where: { userId } });
374	   374	  if (!p || (p.lastSyncAt && Date.now() - p.lastSyncAt.getTime() < maxAgeMs)) return;
375	   375	  if (p.endedAt && p.lastSyncAt && p.lastSyncAt > p.endedAt) return;
376	   376	  try { await reconcileSubscription(p.stripeSubscriptionId); } catch (e) { console.error("[cyrus-tokens] reconcile failed", userId, (e as Error).message); }
377	   377	}
