383	   383	export async function changePlan(user: User, tier: PlanTier): Promise<{ ok: true; message: string } | { ok: false; error: string }> {
384	   384	  const p = await db.cyrusPlan.findUnique({ where: { userId: user.id } });
385	   385	  if (!p || !ACTIVE.includes(p.status) || p.endedAt) return { ok: false, error: "You don't have an active plan." };
386	   386	  if (p.priceTier === tier && !p.cancelAtPeriodEnd) return { ok: false, error: "That's already your plan." };
387	   387	  const price = (await planPrices())[tier];
388	   388	  if (!price) return { ok: false, error: "Plans aren't set up yet." };
389	   389	  const sub = await sc().subscriptions.retrieve(p.stripeSubscriptionId);
390	   390	  const item = sub.items.data[0];
391	   391	  const up = TIER_RANK[tier] > TIER_RANK[p.tier as PlanTier];
392	   392	  try {
393	   393	    await sc().subscriptions.update(sub.id, {
394	   394	      items: [{ id: item.id, price: price.id }],
395	   395	      // Upgrade: charge the prorated difference now, unlock now, grant tokens for what was paid.
396	   396	      // Downgrade: no refund; the cheaper price (and tier) starts with the next renewal.
397	   397	      proration_behavior: up ? "always_invoice" : "none",
398	   398	      ...(up ? { payment_behavior: "error_if_incomplete" as const } : {}),
399	   399	      cancel_at_period_end: false,
400	   400	      metadata: { ...sub.metadata, cyrusTier: tier },
401	   401	    });
402	   402	  } catch (e) {
403	   403	    return { ok: false, error: (e as { message?: string }).message?.includes("authentication") ? "Your bank needs to confirm this payment. Please try again." : "We couldn't change your plan. Your card was not charged." };
404	   404	  }
405	   405	  await reconcileSubscription(sub.id);
406	   406	  return { ok: true, message: up ? "Upgraded. Your new models are unlocked." : "Done. Your plan changes at your next renewal; you keep your current models until then." };
407	   407	}
