421	   421	/**
422	   422	 * A refunded payment takes back the UNSPENT tokens it bought, in proportion to the amount
423	   423	 * refunded (from that purchase's own lot only; tokens already spent stay spent).
424	   424	 */
425	   425	export async function handleRefundedCharge(ch: Stripe.Charge): Promise<number> {
426	   426	  const pi = idOf(ch.payment_intent as string | { id: string } | null);
427	   427	  if (!pi || !ch.amount || !ch.amount_refunded) return 0;
428	   428	  const rows = await db.cyrusTokenLedger.findMany({ where: { kind: "purchase", meta: { path: ["paymentIntent"], equals: pi } } });
429	   429	  let total = 0;
430	   430	  for (const row of rows) {
431	   431	    if (!row.lotId || row.delta <= 0) continue;
432	   432	    const want = Math.round(row.delta * Math.min(1, ch.amount_refunded / ch.amount));
433	   433	    const prior = await db.cyrusTokenLedger.findMany({ where: { kind: "revoke", sourceRef: row.id } });
434	   434	    const already = prior.reduce((a, x) => a + ((x.meta as { requested?: number } | null)?.requested ?? 0), 0);
435	   435	    if (want - already <= 0) continue;
436	   436	    const r = await revokeTokens({ userId: row.userId, amount: want - already, lotIds: [row.lotId], sourceRef: row.id, idemKey: `refund:${ch.id}:${ch.amount_refunded}:${row.id}`, note: `Refund ${ch.id}`, meta: { charge: ch.id, refunded: ch.amount_refunded } });
437	   437	    if (r.created) total += r.revoked;
438	   438	  }
439	   439	  return total;
440	   440	}
