  1	// Cyrus purchases through the payment provider (Nxeon: one Stripe + one wallet), started on either host.
  2	// HOST SEAM: wallet + event delivery come from host.billing; no Nxeon imports.
  3	//
  4	//   applyPurchaseEvent  THE credit/reverse step for a purchase, keyed by the SAME idemKey the direct path uses, so the
  5	//                       direct call, the signed webhook (Cyrus apart), a redelivery and the reconcile sweep can all
  6	//                       run it and tokens land exactly once. purchase.refunded takes back unspent tokens of that lot.
  7	//   deliverPurchase     direct (one app, default) or, with CYRUS_PURCHASE_EVENTS=1 and host.billing.emitPurchase,
  8	//                       the signed webhook/outbox path -> state "pending" until the receiver applies it.
  9	//   payTopupWithWallet  wallet top-up saga (flag CYRUS_WALLET_PAY): idempotent wallet charge (reference) -> deliver
 10	//                       -> on a failed credit, compensating refund; a lost step is found by reconcileWalletTopups.
 11	import { cyrusDb as db } from "../db";
 12	import { getHost } from "../host";
 13	import type { PurchaseEnvelope } from "../host/types";
 14	import { loadTokenConfig } from "./config";
 15	import { topupTokens, validTopupCents, fmt } from "./economy";
 16	import { creditTokens, revokeTokens } from "./ledger";
 17	
 18	const DAY = 86_400_000;
 19	const locks = new Set<string>();
 20	export const walletPayEnabled = (env: Record<string, string | undefined> = process.env) => env.CYRUS_WALLET_PAY === "1";
 21	export const purchaseEventsEnabled = (env: Record<string, string | undefined> = process.env) => env.CYRUS_PURCHASE_EVENTS === "1";
 22	
 23	export function purchaseEnvelope(type: PurchaseEnvelope["type"], subject: string, data: PurchaseEnvelope["data"], now = new Date()): PurchaseEnvelope {
 24	  return { id: `pe_${data.idemKey}${type === "purchase.refunded" ? `:r${data.refundedCents ?? 0}` : ""}`.slice(0, 160), type, createdAt: now.toISOString(), subject, data };
 25	}
 26	
 27	export type ApplyResult = { applied: boolean; tokens: number };
 28	
 29	/** Idempotent. Completed -> a token lot; refunded -> unspent tokens of that lot back (pro rata to the refund). */
 30	export async function applyPurchaseEvent(e: PurchaseEnvelope): Promise<ApplyResult> {
 31	  const d = e.data;
 32	  if (!/^[A-Za-z0-9:_-]{6,160}$/.test(d.idemKey) || !e.subject) throw new Error("invalid purchase event");
 33	  if (e.type === "purchase.completed") {
 34	    const r = await creditTokens({
 35	      userId: e.subject, amount: d.tokens, kind: "purchase", source: "topup", idemKey: d.idemKey,
 36	      sourceRef: typeof d.sourceRef === "string" && /^[A-Za-z0-9:_-]{1,200}$/.test(d.sourceRef) ? d.sourceRef : d.idemKey,
 37	      expiresAt: d.expiresAt ? new Date(d.expiresAt) : null, note: d.note,
 38	      meta: {
 39	        paidCents: d.cents, method: d.method, event: e.id,
 40	        // r44: card top-ups keep the facts revenue/reconciliation read (only well-formed values cross the wire)
 41	        ...(typeof d.paymentIntent === "string" && /^pi_[A-Za-z0-9_]{1,200}$/.test(d.paymentIntent) ? { paymentIntent: d.paymentIntent } : {}),
 42	        ...(typeof d.livemode === "boolean" ? { livemode: d.livemode } : {}),
 43	      },
 44	    });
 45	    return { applied: r.created, tokens: r.created ? r.amount : 0 };
 46	  }
 47	  const row = await db.cyrusTokenLedger.findUnique({ where: { idemKey: d.idemKey } });
 48	  if (!row?.lotId || row.delta <= 0 || row.userId !== e.subject || !d.cents) return { applied: false, tokens: 0 };
 49	  const want = Math.round(row.delta * Math.min(1, (d.refundedCents ?? 0) / d.cents));
 50	  // r49 (re-audit C-L4): refundedCents is CUMULATIVE (Stripe's amount_refunded), so take back only what earlier refund
 51	  // events of this purchase did not already ask for (same rule as billing.ts handleRefundedCharge)
 52	  const prior = await db.cyrusTokenLedger.findMany({ where: { kind: "revoke", sourceRef: row.id } });
 53	  const already = prior.reduce((a, x) => a + ((x.meta as { requested?: number } | null)?.requested ?? 0), 0);
 54	  if (want - already <= 0) return { applied: false, tokens: 0 };
 55	  const r = await revokeTokens({ userId: row.userId, amount: want - already, lotIds: [row.lotId], sourceRef: row.id, idemKey: `refund:${d.idemKey}:${d.refundedCents ?? 0}`, note: `Refund ${d.idemKey}`, meta: { refundedCents: d.refundedCents ?? 0 } });
 56	  return { applied: r.created, tokens: r.revoked };
 57	}
