 60	export async function deliverPurchase(e: PurchaseEnvelope): Promise<{ state: "credited" | "pending"; tokens: number }> {
 61	  const emit = getHost().billing.emitPurchase;
 62	  if (purchaseEventsEnabled() && emit) {
 63	    await emit(e);
 64	    return { state: "pending", tokens: 0 };
 65	  }
 66	  const r = await applyPurchaseEvent(e);
 67	  return { state: "credited", tokens: r.tokens };
