 70	export type WalletPayState = "credited" | "pending" | "insufficient_funds" | "failed" | "unavailable" | "in_progress" | "invalid";
 71	export const walletRef = (userId: string, key: string) => `cwt:${userId}:${key}`;
 72	
 73	/** Status of a wallet top-up by its key: honest, from the ledger and the wallet itself. */
 74	export async function walletTopupStatus(userId: string, key: string): Promise<WalletPayState> {
 75	  const ref = walletRef(userId, key);
 76	  if (await db.cyrusTokenLedger.findUnique({ where: { idemKey: ref }, select: { id: true } })) return "credited";
 77	  const w = getHost().billing.wallet;
 78	  const moves = (await w?.findByReference?.({ userId, prefix: ref, sinceMs: Date.now() - 30 * DAY })) ?? [];
 79	  const charged = moves.some((m) => m.reference === ref && m.cents < 0);
 80	  const refunded = moves.some((m) => m.reference === `${ref}:refund` && m.cents > 0);
 81	  return refunded ? "failed" : charged ? "pending" : "invalid";
 82	}
