 84	export async function payTopupWithWallet(user: { id: string }, cents: number, key: string): Promise<{ state: WalletPayState; tokens: number; error?: string }> {
 85	  const wallet = getHost().billing.wallet;
 86	  if (!walletPayEnabled() || !wallet) return { state: "unavailable", tokens: 0, error: "Paying with your wallet isn't available right now." };
 87	  if (!/^[A-Za-z0-9_-]{16,64}$/.test(key)) return { state: "invalid", tokens: 0, error: "Missing purchase key." };
 88	  const cfg = await loadTokenConfig();
 89	  if (!cfg.topup.enabled) return { state: "unavailable", tokens: 0, error: "Top-ups aren't available right now." };
 90	  if (!validTopupCents(cents, cfg)) return { state: "invalid", tokens: 0, error: `Pick an amount from $${(cfg.topup.minCents / 100).toFixed(0)} to $${(cfg.topup.maxCents / 100).toFixed(0)}.` };
 91	  if (cfg.topup.requiresPaid) {
 92	    const paid = (await getHost().servers.paidCount(user.id)) + (await db.cyrusPlan.count({ where: { userId: user.id } }));
 93	    if (!paid) return { state: "invalid", tokens: 0, error: "Top-ups are for customers with a game server or a Cyrus plan." };
 94	  }
 95	  const ref = walletRef(user.id, key);
 96	  if (locks.has(ref)) return { state: "in_progress", tokens: 0 };
 97	  locks.add(ref);
 98	  try {
 99	    if (await db.cyrusTokenLedger.findUnique({ where: { idemKey: ref }, select: { id: true } })) return { state: "credited", tokens: 0 };
100	    const tokens = topupTokens(cents, cfg);
101	    const charge = await wallet.charge({ userId: user.id, cents, description: `Cyrus tokens: ${fmt(tokens)}`, reference: ref });
102	    if (!charge.ok) return { state: charge.error === "insufficient_funds" ? "insufficient_funds" : "invalid", tokens: 0, error: charge.error === "insufficient_funds" ? "Not enough in your wallet. Add funds or pay by card." : "Couldn't charge your wallet." };
103	    const e = purchaseEnvelope("purchase.completed", user.id, {
104	      idemKey: ref, kind: "topup", method: "wallet", tokens, cents,
105	      expiresAt: new Date(Date.now() + cfg.topup.expiryDays * DAY).toISOString(), note: `Top-up $${(cents / 100).toFixed(2)} (wallet)`,
106	    });
107	    try {
108	      const r = await deliverPurchase(e);
109	      return { state: r.state, tokens: r.tokens };
110	    } catch (err) {
111	      console.error("[cyrus-purchase] credit failed after wallet charge", ref, (err as Error).message);
112	      // Compensate: the money goes back, the purchase is honestly failed. If the refund fails too, the charge stays
113	      // "pending" and reconcileWalletTopups credits it later.
114	      try {
115	        await wallet.refund({ userId: user.id, cents, description: "Refund: Cyrus tokens not credited", reference: `${ref}:refund` });
116	        return { state: "failed", tokens: 0, error: "We couldn't add your tokens, so your wallet was refunded." };
117	      } catch {
118	        return { state: "pending", tokens: 0, error: "Your tokens are on the way. If they don't appear in a few minutes, contact support." };
119	      }
120	    }
121	  } finally {
122	    locks.delete(ref);
123	  }
124	}
