134	/** r44 reconciliation for card top-ups on the event path: a paid session whose event never landed (dead sender row,
135	 *  lost process) is applied directly, once (same idemKey). Only runs with CYRUS_PURCHASE_EVENTS=1 (direct mode cannot
136	 *  lose one). `sessions` = recent paid Cyrus top-up sessions from the payment provider. */
137	export async function reconcileCardTopups(envelopes: PurchaseEnvelope[], minAgeMs = 15 * 60_000, now = new Date()): Promise<{ checked: number; credited: number }> {
138	  if (!purchaseEventsEnabled()) return { checked: 0, credited: 0 };
139	  let checked = 0, credited = 0;
140	  for (const e of envelopes) {
141	    if (now.getTime() - Date.parse(e.createdAt) < minAgeMs) continue; // give the event path time first
142	    checked++;
143	    if (await db.cyrusTokenLedger.findUnique({ where: { idemKey: e.data.idemKey }, select: { id: true } })) continue;
144	    if ((await applyPurchaseEvent(e)).applied) credited++;
145	  }
146	  return { checked, credited };
147	}
