149	/** Reconciliation: any referenced wallet charge without a ledger row (and without a refund) is credited. */
150	export async function reconcileWalletTopups(o: { userId?: string; sinceMs?: number } = {}): Promise<{ checked: number; credited: number }> {
151	  const w = getHost().billing.wallet;
152	  if (!walletPayEnabled() || !w?.findByReference) return { checked: 0, credited: 0 };
153	  const cfg = await loadTokenConfig();
154	  const moves = await w.findByReference({ userId: o.userId, prefix: "cwt:", sinceMs: o.sinceMs ?? Date.now() - 7 * DAY });
155	  const refunded = new Set(moves.filter((m) => m.cents > 0 && m.reference.endsWith(":refund")).map((m) => m.reference.slice(0, -":refund".length)));
156	  let credited = 0, checked = 0;
157	  for (const m of moves) {
158	    if (m.cents >= 0 || refunded.has(m.reference) || locks.has(m.reference)) continue;
159	    checked++;
160	    if (await db.cyrusTokenLedger.findUnique({ where: { idemKey: m.reference }, select: { id: true } })) continue;
161	    const cents = -m.cents;
162	    const r = await applyPurchaseEvent(purchaseEnvelope("purchase.completed", m.userId, {
163	      idemKey: m.reference, kind: "topup", method: "wallet", tokens: topupTokens(cents, cfg), cents,
164	      expiresAt: new Date(m.at.getTime() + cfg.topup.expiryDays * DAY).toISOString(), note: `Top-up $${(cents / 100).toFixed(2)} (wallet, reconciled)`,
165	    }));
166	    if (r.applied) credited++;
167	  }
168	  return { checked, credited };
169	}
