171	/** Refund a wallet top-up: unspent tokens of that lot come back first, then the matching share of money. */
172	export async function refundWalletTopup(userId: string, key: string): Promise<{ ok: boolean; tokens: number; cents: number }> {
173	  const ref = walletRef(userId, key);
174	  const w = getHost().billing.wallet;
175	  const row = await db.cyrusTokenLedger.findUnique({ where: { idemKey: ref } });
176	  const paid = (row?.meta as { paidCents?: number } | null)?.paidCents ?? 0;
177	  if (!w || !row || row.userId !== userId || !paid || row.delta <= 0) return { ok: false, tokens: 0, cents: 0 };
178	  const lot = row.lotId ? await db.cyrusTokenLot.findUnique({ where: { id: row.lotId } }) : null;
179	  const unspent = Math.min(row.delta, lot?.remaining ?? 0);
180	  const cents = Math.floor((paid * unspent) / row.delta);
181	  if (!cents) return { ok: false, tokens: 0, cents: 0 };
182	  const r = await applyPurchaseEvent(purchaseEnvelope("purchase.refunded", userId, { idemKey: ref, kind: "topup", method: "wallet", tokens: row.delta, cents: paid, expiresAt: null, note: null, refundedCents: cents }));
183	  if (r.tokens <= 0) return { ok: false, tokens: 0, cents: 0 };
184	  const money = Math.floor((paid * r.tokens) / row.delta);
185	  await w.refund({ userId, cents: money, description: "Refund: unused Cyrus tokens", reference: `${ref}:refund` });
186	  return { ok: true, tokens: r.tokens, cents: money };
187	}
188	// Cyrus tokens that come with a game server: once on purchase, again on every paid
189	// renewal (less than the first grant). Server only; plain module (called from the worker's
190	// renewal sweep and from placeGameOrder / renewNow). Every entry point is BEST-EFFORT:
191	// callers wrap it so a token hiccup can never fail an order or a renewal.
192	//
193	// Idempotent per server + period: `gs:<serverId>:initial`, `gs:<serverId>:renew:<periodStartISO>`.
194	// A webhook retry, a re-run sweep or a double "Renew now" never grants twice.
195	import { cyrusDb as db } from "../db";
196	import { loadTokenConfig } from "./config";
197	import { serverGrant } from "./economy";
198	import { creditTokens, revokeTokens, type CreditResult, type Tx } from "./ledger";
199	import { tokensActiveForUserId } from "./access";
200	import { earnsCyrusTokens } from "./games";
201	import { getHost } from "../host";
202	
203	const DAY = 86_400_000;
204	export const initialKey = (serverId: string) => `gs:${serverId}:initial`;
205	export const renewalKey = (serverId: string, periodStart: Date) => `gs:${serverId}:renew:${periodStart.toISOString()}`;
206	
207	type GrantCtx = { userId: string; serverId: string; gameFamily?: string | null };
208	
209	async function eligible(c: GrantCtx): Promise<boolean> {
210	  const cfg = await loadTokenConfig();
211	  // r41 scope (PLACEHOLDER setting cyrus_tok_grant_scope): cyrus_games = servers of a game Cyrus builds for (registry
212	  // status "live", the pre-r41 rule); all_game_servers = any game server; all_servers = any paid Nxeon server.
213	  if (cfg.grant.scope !== "all_servers") {
214	    const fam = c.gameFamily ?? await getHost().servers.planFamily(c.serverId);
215	    if (cfg.grant.scope === "cyrus_games" ? !earnsCyrusTokens(fam) : !fam) return false;
216	  }
217	  return tokensActiveForUserId(c.userId, cfg);
218	}
