220	/** Tokens this server has ever been granted (gross: a reversal does not make room again), for the per-server lifetime cap. */
221	async function serverLifetime(tx: Tx, serverId: string) {
222	  const a = await tx.cyrusTokenLedger.aggregate({ where: { sourceRef: serverId, source: { in: ["server_initial", "server_renewal"] }, kind: "grant" }, _sum: { delta: true } });
223	  return a._sum.delta ?? 0;
224	}
