226	/** Apply the per-server lifetime cap and the per-account held cap (in that order). */
227	async function capServerGrant(tx: Tx, userId: string, serverId: string, amount: number, at: Date, cfg: Awaited<ReturnType<typeof loadTokenConfig>>) {
228	  let note: string | undefined;
229	  if (cfg.grant.perServerCap > 0) {
230	    const room = Math.max(0, cfg.grant.perServerCap - (await serverLifetime(tx, serverId)));
231	    if (amount > room) { amount = room; note = `capped at ${cfg.grant.perServerCap} tokens per server`; }
232	  }
233	  const held = await serverGrantBalance(tx, userId, at);
234	  const room = Math.max(0, cfg.grant.balanceCap - held);
235	  if (amount > room) { amount = room; note = `capped at ${cfg.grant.balanceCap} server tokens held`; }
236	  return { amount, note };
237	}
