239	/** Server-grant tokens the account still holds, for the per-account cap. */
240	async function serverGrantBalance(tx: Tx, userId: string, now: Date) {
241	  const a = await tx.cyrusTokenLot.aggregate({
242	    where: { userId, source: { in: ["server_initial", "server_renewal"] }, remaining: { gt: 0 }, OR: [{ expiresAt: null }, { expiresAt: { gt: now } }] },
243	    _sum: { remaining: true },
244	  });
245	  return a._sum.remaining ?? 0;
246	}
