248	/**
249	 * Purchase grant. `chargeCents` is what the order actually charged for `termMonths`
250	 * (after coupons/partner discounts, pre-tax); a $0 order (trial) earns nothing now and
251	 * gets its initial grant on its first paid renewal instead.
252	 */
253	export async function grantForGameServerPurchase(c: GrantCtx & { chargeCents: number; termMonths: number; now?: Date }): Promise<CreditResult | null> {
254	  if (!(c.chargeCents > 0)) return null;
255	  if (!(await eligible(c))) return null;
256	  const cfg = await loadTokenConfig();
257	  const term = Math.max(1, Math.round(c.termMonths || 1));
258	  const monthlyCents = Math.round(c.chargeCents / term);
259	  const g = serverGrant("initial", monthlyCents, term, cfg);
260	  if (!g.tokens) return null;
261	  const now = c.now ?? new Date();
262	  return creditTokens({
263	    userId: c.userId,
264	    amount: g.tokens,
265	    kind: "grant",
266	    source: "server_initial",
267	    sourceRef: c.serverId,
268	    idemKey: initialKey(c.serverId),
269	    expiresAt: new Date(now.getTime() + g.expiresInDays * DAY),
270	    note: "Game server purchase",
271	    meta: { monthlyCents, termMonths: term, formula: { initialPerMonth: g.initialPerMonth, renewPerMonth: g.renewPerMonth, months: g.months } },
272	    now,
273	    clamp: async (tx, amount, at) => {
274	      // Abuse limits: a handful of initial grants per 30 days, and a ceiling on held server tokens.
275	      const recent = await tx.cyrusTokenLedger.count({ where: { userId: c.userId, source: "server_initial", kind: "grant", delta: { gt: 0 }, createdAt: { gt: new Date(at.getTime() - 30 * DAY) } } });
276	      if (recent >= cfg.grant.maxInitialPer30d) return { amount: 0, note: `capped: ${recent} server grants in 30 days` };
277	      return capServerGrant(tx, c.userId, c.serverId, amount, at, cfg);
278	    },
279	  });
280	}
