282	/**
283	 * Paid-renewal grant. `netCents` = the renewal's pre-tax charge for `months`. If this server
284	 * never got its initial grant (bought with a $0 trial, or before tokens existed for this
285	 * account) the first paid renewal earns the initial amount instead.
286	 */
287	export async function grantForGameServerRenewal(c: GrantCtx & { netCents: number; months: number; periodStart: Date; now?: Date }): Promise<CreditResult | null> {
288	  if (!(c.netCents > 0)) return null;
289	  if (!(await eligible(c))) return null;
290	  const had = await db.cyrusTokenLedger.findUnique({ where: { idemKey: initialKey(c.serverId) }, select: { id: true } });
291	  if (!had) return grantForGameServerPurchase({ userId: c.userId, serverId: c.serverId, gameFamily: c.gameFamily, chargeCents: c.netCents, termMonths: c.months, now: c.now });
292	  const cfg = await loadTokenConfig();
293	  const months = Math.max(1, Math.round(c.months || 1));
294	  const monthlyCents = Math.round(c.netCents / months);
295	  const g = serverGrant("renewal", monthlyCents, months, cfg);
296	  if (!g.tokens) return null;
297	  const now = c.now ?? new Date();
298	  return creditTokens({
299	    userId: c.userId,
300	    amount: g.tokens,
301	    kind: "grant",
302	    source: "server_renewal",
303	    sourceRef: c.serverId,
304	    idemKey: renewalKey(c.serverId, c.periodStart),
305	    expiresAt: new Date(now.getTime() + g.expiresInDays * DAY),
306	    note: "Game server renewal",
307	    meta: { monthlyCents, months, periodStart: c.periodStart.toISOString() },
308	    now,
309	    clamp: (tx, amount, at) => capServerGrant(tx, c.userId, c.serverId, amount, at, cfg),
310	  });
311	}
