313	export type ReverseReason = "refund" | "cancel" | "deleted";
314	
315	/**
316	 * r41: take back a server's UNSPENT grant tokens (never below zero, never tokens a running build holds). `refund` and
317	 * `cancel` always reverse; `deleted` only within cyrus_tok_grant_clawback_days of the server's first grant (deploy and
318	 * delete farming). Idempotent per server + reason + ref (`gs:<serverId>:reverse:<reason>:<ref>`).
319	 */
320	export async function reverseServerGrants(c: { userId: string; serverId: string; reason: ReverseReason; ref?: string | null; now?: Date }): Promise<{ revoked: number; skipped?: string }> {
321	  const now = c.now ?? new Date();
322	  const cfg = await loadTokenConfig();
323	  const first = await db.cyrusTokenLedger.findUnique({ where: { idemKey: initialKey(c.serverId) }, select: { userId: true, createdAt: true } });
324	  if (!first || first.userId !== c.userId) return { revoked: 0, skipped: "no grant" };
325	  if (c.reason === "deleted" && !(cfg.grant.clawbackDays > 0 && now.getTime() - first.createdAt.getTime() <= cfg.grant.clawbackDays * DAY)) return { revoked: 0, skipped: "outside clawback window" };
326	  const lots = await db.cyrusTokenLot.findMany({ where: { userId: c.userId, sourceRef: c.serverId, source: { in: ["server_initial", "server_renewal"] }, remaining: { gt: 0 } }, select: { id: true, remaining: true } });
327	  const want = lots.reduce((a, l) => a + l.remaining, 0);
328	  const ref = (c.ref ?? "once").replace(/[^A-Za-z0-9_:.-]/g, "").slice(0, 80) || "once";
329	  const r = await revokeTokens({
330	    userId: c.userId, amount: want, lotIds: lots.map((l) => l.id), sourceRef: c.serverId, now,
331	    idemKey: `gs:${c.serverId}:reverse:${c.reason}:${ref}`,
332	    note: c.reason === "refund" ? "Server refunded" : c.reason === "cancel" ? "Server cancelled" : "Server deleted soon after deploy",
333	    meta: { serverId: c.serverId, reason: c.reason },
334	  });
335	  return { revoked: r.revoked };
336	}
