  1	// Cyrus token ledger: the ONLY code that moves tokens. Server only; plain module
  2	// (safe in the worker). See docs/DOCUMENTATION.md "Cyrus token economy".
  3	//
  4	// Invariants:
  5	//  - Every write runs in one transaction that first locks the account row (FOR UPDATE),
  6	//    so all of one account's token operations are serialised.
  7	//  - CyrusTokenLedger is append-only; `idemKey` is UNIQUE. An operation whose key already
  8	//    exists is a no-op that reports `created: false` (webhook retries, re-runs, double clicks).
  9	//  - Balance = SUM(lot.remaining) over unexpired lots. Due lots are expired (with a ledger
 10	//    row) at the start of every operation, so a stale lot is never spent.
 11	//  - Reserving moves nothing: it only raises `reserved`. Settling spends the ACTUAL cost
 12	//    from lots (soonest-expiring first) and drops the hold. Nothing goes below zero; a cost
 13	//    above what the account holds is recorded as a write-off (Nxeon absorbs it).
 14	import { Prisma } from "@prisma/client";
 15	import { cyrusDb as db } from "../db";
 16	import { loadTokenConfig } from "./config";
 17	import { planTokensFrozen } from "./rollover";
 18	
 19	export type Tx = Prisma.TransactionClient;
 20	const DAY = 86_400_000;
 21	
 22	export type LedgerKind = "grant" | "purchase" | "reserve" | "spend" | "release" | "refund" | "expire" | "revoke";
 23	export type LotSource = "server_initial" | "server_renewal" | "plan" | "topup" | "admin" | "refund";
 24	
 25	class Duplicate extends Error {}
 26	
 27	function isUniqueViolation(e: unknown): boolean {
 28	  return (e as { code?: string })?.code === "P2002";
 29	}
 30	
 31	async function lock(tx: Tx, userId: string): Promise<{ createdAt: Date }> {
 32	  await tx.$executeRaw`INSERT INTO "CyrusTokenAccount" ("userId", "updatedAt") VALUES (${userId}, now()) ON CONFLICT ("userId") DO NOTHING`;
 33	  const rows = await tx.$queryRaw<{ createdAt: Date }[]>`SELECT "createdAt" FROM "CyrusTokenAccount" WHERE "userId" = ${userId} FOR UPDATE`;
 34	  return rows[0];
 35	}
 36	
 37	async function sums(tx: Tx, userId: string): Promise<{ balance: number; reserved: number }> {
 38	  const [b, r] = await Promise.all([
 39	    tx.cyrusTokenLot.aggregate({ where: { userId, remaining: { gt: 0 } }, _sum: { remaining: true } }),
 40	    tx.cyrusTokenReservation.aggregate({ where: { userId, status: "held" }, _sum: { amount: true } }),
 41	  ]);
 42	  return { balance: b._sum.remaining ?? 0, reserved: r._sum.amount ?? 0 };
 43	}
