 45	/** r41: lot sources that are frozen right now (a lapsed plan under the freeze rule): held, not spendable. */
 46	async function frozenSources(tx: Tx, userId: string, now: Date): Promise<LotSource[]> {
 47	  const plan = await tx.cyrusPlan.findUnique({ where: { userId }, select: { status: true, endedAt: true, currentPeriodEnd: true } });
 48	  if (!plan) return [];
 49	  return planTokensFrozen(plan, await loadTokenConfig(), now) ? ["plan"] : [];
 50	}
