 58	async function store(tx: Tx, userId: string, extra: Prisma.CyrusTokenAccountUpdateInput = {}): Promise<{ balance: number; reserved: number }> {
 59	  const s = await sums(tx, userId);
 60	  await tx.cyrusTokenAccount.update({ where: { userId }, data: { balance: s.balance, reserved: s.reserved, ...extra } });
 61	  return s;
