 76	/** Expire every due lot of this account (one ledger row per lot, idempotent per lot). */
 77	async function expireDue(tx: Tx, userId: string, now: Date): Promise<number> {
 78	  const due = await tx.cyrusTokenLot.findMany({ where: { userId, remaining: { gt: 0 }, expiresAt: { lte: now } }, orderBy: { expiresAt: "asc" } });
 79	  let total = 0;
 80	  for (const lot of due) {
 81	    const key = `expire:${lot.id}`;
 82	    if (await exists(tx, key)) continue;
 83	    await tx.cyrusTokenLot.update({ where: { id: lot.id }, data: { remaining: 0 } });
 84	    total += lot.remaining;
 85	    const after = await sums(tx, userId);
 86	    await writeLedger(tx, userId, { kind: "expire", delta: -lot.remaining, idemKey: key, source: lot.source, sourceRef: lot.sourceRef, lotId: lot.id, note: "expired" }, after);
 87	  }
 88	  if (due.length) await store(tx, userId);
 89	  return total;
 90	}
