 92	/** Take up to `amount` from the account's lots, soonest-expiring first. */
 93	async function drawLots(tx: Tx, userId: string, amount: number, where: Prisma.CyrusTokenLotWhereInput = {}): Promise<{ taken: number; draws: { lotId: string; n: number }[] }> {
 94	  if (amount <= 0) return { taken: 0, draws: [] };
 95	  const lots = await tx.cyrusTokenLot.findMany({
 96	    where: { userId, remaining: { gt: 0 }, ...where },
 97	    orderBy: [{ expiresAt: { sort: "asc", nulls: "last" } }, { createdAt: "asc" }],
 98	  });
 99	  let left = amount;
100	  const draws: { lotId: string; n: number }[] = [];
101	  for (const lot of lots) {
102	    if (left <= 0) break;
103	    const n = Math.min(left, lot.remaining);
104	    await tx.cyrusTokenLot.update({ where: { id: lot.id }, data: { remaining: lot.remaining - n } });
105	    draws.push({ lotId: lot.id, n });
106	    left -= n;
107	  }
108	  return { taken: amount - left, draws };
109	}
