111	async function run<T>(userId: string, fn: (tx: Tx, acct: { createdAt: Date }) => Promise<T>): Promise<T | typeof DUP> {
112	  try {
113	    return await db.$transaction(async (tx) => fn(tx, await lock(tx, userId)), { timeout: 20_000, maxWait: 10_000 });
114	  } catch (e) {
115	    if (e instanceof Duplicate || isUniqueViolation(e)) return DUP;
116	    throw e;
117	  }
118	}
