125	export type CreditInput = {
126	  userId: string;
127	  amount: number;
128	  kind: "grant" | "purchase" | "refund";
129	  source: LotSource;
130	  sourceRef?: string | null;
131	  idemKey: string;
132	  expiresAt?: Date | null;
133	  note?: string | null;
134	  meta?: Prisma.InputJsonValue;
135	  actorId?: string | null;
136	  now?: Date;
137	  /** Runs under the account lock before crediting: cap the amount (abuse limits). */
138	  clamp?: (tx: Tx, amount: number, now: Date) => Promise<{ amount: number; note?: string }>;
139	};
