143	/** Add tokens (a new lot). Idempotent on idemKey; a zero amount still writes the row (so a capped grant is final). */
144	export async function creditTokens(i: CreditInput): Promise<CreditResult> {
145	  const now = i.now ?? new Date();
146	  const r = await run(i.userId, async (tx) => {
147	    if (await exists(tx, i.idemKey)) throw new Duplicate();
148	    await expireDue(tx, i.userId, now);
149	    let amount = Math.max(0, Math.floor(i.amount));
150	    let note = i.note ?? null;
151	    if (i.clamp) {
152	      const c = await i.clamp(tx, amount, now);
153	      if (c.amount < amount) note = [note, c.note].filter(Boolean).join("; ") || null;
154	      amount = Math.max(0, Math.floor(c.amount));
155	    }
156	    let lotId: string | null = null;
157	    if (amount > 0) {
158	      const lot = await tx.cyrusTokenLot.create({ data: { userId: i.userId, source: i.source, sourceRef: i.sourceRef ?? null, amount, remaining: amount, expiresAt: i.expiresAt ?? null } });
159	      lotId = lot.id;
160	    }
161	    const after = await store(tx, i.userId, amount > 0 ? { lifetimeGranted: { increment: amount } } : {});
162	    await writeLedger(tx, i.userId, { kind: i.kind, delta: amount, idemKey: i.idemKey, source: i.source, sourceRef: i.sourceRef ?? null, lotId, note, meta: i.meta, actorId: i.actorId ?? null }, after);
163	    return { created: true, amount, lotId, note };
164	  });
165	  if (r === DUP) {
166	    const prev = await db.cyrusTokenLedger.findUnique({ where: { idemKey: i.idemKey } });
167	    return { created: false, amount: prev?.delta ?? 0, lotId: prev?.lotId ?? null, note: prev?.note };
168	  }
169	  return r;
170	}
