176	export type ReserveResult =
177	  | { ok: true; amount: number; created: boolean; available: number }
178	  | { ok: false; code: "insufficient_tokens" | "daily_cap"; available: number; need: number; usedToday?: number; cap?: number };
179	
180	/**
181	 * Hold tokens for a build. `pick(available)` returns the amount to hold (or null = not
182	 * enough). `dailyCap(createdAt)` bounds reserve+spend per rolling 24 h. Idempotent per buildId.
183	 */
184	export async function reserveTokens(i: {
185	  userId: string; buildId: string; model: string; need: number;
186	  pick: (available: number) => number | null;
187	  dailyCap: (accountCreatedAt: Date) => number;
188	  allowShort?: boolean;
189	  now?: Date;
190	}): Promise<ReserveResult> {
191	  const now = i.now ?? new Date();
192	  const r = await run(i.userId, async (tx, acct) => {
193	    const prev = await tx.cyrusTokenReservation.findUnique({ where: { buildId: i.buildId } });
194	    if (prev) return { ok: true as const, amount: prev.amount, created: false, available: 0 };
195	    await expireDue(tx, i.userId, now);
196	    const s = await sums(tx, i.userId);
197	    const frozen = await frozenAmount(tx, i.userId, await frozenSources(tx, i.userId, now));
198	    const available = Math.max(0, s.balance - frozen - s.reserved);
199	    let amount = i.pick(available);
200	    if (amount === null) {
201	      if (!i.allowShort) return { ok: false as const, code: "insufficient_tokens" as const, available, need: i.need };
202	      amount = Math.min(available, i.need);
203	    }
204	    const since = new Date(now.getTime() - DAY);
205	    const recent = await tx.cyrusTokenReservation.findMany({ where: { userId: i.userId, createdAt: { gt: since } }, select: { status: true, amount: true, charged: true } });
206	    const usedToday = recent.reduce((a, x) => a + (x.status === "held" ? x.amount : x.charged ?? 0), 0);
207	    const cap = i.dailyCap(acct.createdAt);
208	    if (!i.allowShort && usedToday + amount > cap) return { ok: false as const, code: "daily_cap" as const, available, need: amount, usedToday, cap };
209	    await tx.cyrusTokenReservation.create({ data: { buildId: i.buildId, userId: i.userId, model: i.model, amount, status: "held", createdAt: now } });
210	    const after = await store(tx, i.userId);
211	    await writeLedger(tx, i.userId, { kind: "reserve", delta: 0, idemKey: `reserve:${i.buildId}`, buildId: i.buildId, model: i.model, meta: { hold: amount } }, after);
212	    return { ok: true as const, amount, created: true, available: available - amount };
213	  });
214	  if (r === DUP) return { ok: true, amount: 0, created: false, available: 0 };
215	  return r;
216	}
