218	export type SettleResult = { settled: boolean; charged: number; writeoff: number; released: number; reason: string };
219	
220	/**
221	 * Finish a build's hold: spend `charge` tokens (the ACTUAL cost, decided by the caller),
222	 * release the rest. Idempotent: a reservation that is no longer held is returned as-is.
223	 */
224	export async function settleReservation(i: { buildId: string; charge: number; reason: string; costUsd?: number | null; now?: Date }): Promise<SettleResult | null> {
225	  const res = await db.cyrusTokenReservation.findUnique({ where: { buildId: i.buildId } });
226	  if (!res) return null;
227	  const now = i.now ?? new Date();
228	  const r = await run(res.userId, async (tx) => {
229	    const cur = await tx.cyrusTokenReservation.findUnique({ where: { buildId: i.buildId } });
230	    if (!cur || cur.status !== "held") return { settled: false, charged: cur?.charged ?? 0, writeoff: 0, released: 0, reason: "already" };
231	    await expireDue(tx, res.userId, now);
232	    const want = Math.max(0, Math.ceil(i.charge));
233	    const fz = await frozenSources(tx, res.userId, now);
234	    const first = await drawLots(tx, res.userId, want, fz.length ? { source: { notIn: fz } } : {});
235	    const rest = fz.length && first.taken < want ? await drawLots(tx, res.userId, want - first.taken, { source: { in: fz } }) : { taken: 0, draws: [] };
236	    const taken = first.taken + rest.taken;
237	    const draws = [...first.draws, ...rest.draws];
238	    const writeoff = want - taken;
239	    await tx.cyrusTokenReservation.update({ where: { buildId: i.buildId }, data: { status: want > 0 ? "settled" : "released", charged: taken, costUsd: i.costUsd ?? null, settledAt: now } });
240	    const after = await store(tx, res.userId, taken > 0 ? { lifetimeSpent: { increment: taken } } : {});
241	    const released = Math.max(0, cur.amount - taken);
242	    await writeLedger(tx, res.userId, {
243	      kind: want > 0 ? "spend" : "release",
244	      delta: -taken,
245	      idemKey: `settle:${i.buildId}`,
246	      buildId: i.buildId,
247	      model: cur.model,
248	      note: i.reason,
249	      meta: { hold: cur.amount, released, writeoff, costUsd: i.costUsd ?? null, draws },
250	    }, after);
251	    return { settled: true, charged: taken, writeoff, released, reason: i.reason };
252	  });
253	  if (r === DUP) return { settled: false, charged: 0, writeoff: 0, released: 0, reason: "already" };
254	  return r;
255	}
