261	/** Remove up to `amount` unspent tokens (refunds, admin revoke). Never below zero. Idempotent. */
262	export async function revokeTokens(i: {
263	  userId: string; amount: number; idemKey: string; note?: string; actorId?: string | null; sourceRef?: string | null;
264	  /** Restrict to these lots (e.g. the lot a refunded invoice granted); falls back to nothing else. */
265	  lotIds?: string[];
266	  meta?: Prisma.InputJsonValue;
267	  now?: Date;
268	}): Promise<{ created: boolean; revoked: number }> {
269	  const now = i.now ?? new Date();
270	  const r = await run(i.userId, async (tx) => {
271	    if (await exists(tx, i.idemKey)) throw new Duplicate();
272	    await expireDue(tx, i.userId, now);
273	    // Never take tokens a running build already holds.
274	    const s0 = await sums(tx, i.userId);
275	    const free = Math.max(0, s0.balance - s0.reserved);
276	    const want = Math.min(Math.max(0, Math.floor(i.amount)), free);
277	    const { taken, draws } = await drawLots(tx, i.userId, want, i.lotIds ? { id: { in: i.lotIds } } : {});
278	    const after = await store(tx, i.userId);
279	    await writeLedger(tx, i.userId, { kind: "revoke", delta: -taken, idemKey: i.idemKey, sourceRef: i.sourceRef ?? null, note: i.note ?? null, actorId: i.actorId ?? null, meta: { requested: i.amount, draws, ...(i.meta && typeof i.meta === "object" ? (i.meta as object) : {}) } }, after);
280	    return { created: true, revoked: taken };
281	  });
282	  if (r === DUP) return { created: false, revoked: 0 };
283	  return r;
284	}
