312	export type TokenSummary = {
313	  balance: number;
314	  reserved: number;
315	  available: number;
316	  /** r41: tokens held but not spendable (a lapsed plan's tokens under the freeze rule). Included in balance. */
317	  frozen: number;
318	  bySource: Record<string, number>;
319	  nextExpiry: { at: string; amount: number } | null;
320	  lifetimeGranted: number;
321	  lifetimeSpent: number;
322	};
