324	/** Live summary (ignores lots that are past expiry but not swept yet). */
325	export async function tokenSummary(userId: string, now = new Date()): Promise<TokenSummary> {
326	  const live = { userId, remaining: { gt: 0 }, OR: [{ expiresAt: null }, { expiresAt: { gt: now } }] };
327	  const [lots, held, acct, plan] = await Promise.all([
328	    db.cyrusTokenLot.findMany({ where: live, select: { source: true, remaining: true, expiresAt: true }, orderBy: { expiresAt: { sort: "asc", nulls: "last" } } }),
329	    db.cyrusTokenReservation.aggregate({ where: { userId, status: "held" }, _sum: { amount: true } }),
330	    db.cyrusTokenAccount.findUnique({ where: { userId } }),
331	    db.cyrusPlan.findUnique({ where: { userId }, select: { status: true, endedAt: true, currentPeriodEnd: true } }),
332	  ]);
333	  const frozenSrc = plan && planTokensFrozen(plan, await loadTokenConfig(), now) ? ["plan"] : [];
334	  const bySource: Record<string, number> = {};
335	  let balance = 0;
336	  for (const l of lots) { balance += l.remaining; bySource[l.source] = (bySource[l.source] ?? 0) + l.remaining; }
337	  const first = lots.find((l) => l.expiresAt);
338	  const reserved = held._sum.amount ?? 0;
339	  const frozen = lots.filter((l) => frozenSrc.includes(l.source)).reduce((a, l) => a + l.remaining, 0);
340	  return {
341	    balance, reserved, available: Math.max(0, balance - frozen - reserved), frozen, bySource,
342	    nextExpiry: first?.expiresAt ? { at: first.expiresAt.toISOString(), amount: lots.filter((l) => l.expiresAt && l.expiresAt.getTime() === first.expiresAt!.getTime()).reduce((a, l) => a + l.remaining, 0) } : null,
343	    lifetimeGranted: acct?.lifetimeGranted ?? 0,
344	    lifetimeSpent: acct?.lifetimeSpent ?? 0,
345	  };
346	}
