348	export async function ledgerPage(userId: string, opts: { take?: number; before?: string | null } = {}) {
349	  const take = Math.min(100, Math.max(1, opts.take ?? 30));
350	  const rows = await db.cyrusTokenLedger.findMany({
351	    where: { userId, ...(opts.before ? { createdAt: { lt: new Date(opts.before) } } : {}) },
352	    orderBy: [{ createdAt: "desc" }, { id: "desc" }],
353	    take: take + 1,
354	  });
355	  return { rows: rows.slice(0, take), more: rows.length > take };
356	}

