97	    97	/** Buy, increase or decrease the add-on, paying from the Nxeon wallet. Idempotent per `key` (one click = one key). */
98	    98	export async function setStorageAddonWallet(user: { id: string }, gb: number, key: string, now = new Date()): Promise<BuyResult> {
99	    99	  const wallet = getHost().billing.wallet;
100	   100	  if (!storageAddonsEnabled() || !wallet) return { state: "unavailable", chargedCents: 0, error: "Buying storage isn't available right now." };
101	   101	  if (!KEY_RE.test(key)) return { state: "invalid", chargedCents: 0, error: "Missing purchase key." };
102	   102	  const cfg = await loadStorageConfig();
103	   103	  if (!Number.isInteger(gb) || gb < 0 || gb > cfg.addonMaxGb) return { state: "invalid", chargedCents: 0, error: `Pick 1 to ${cfg.addonMaxGb} GB.` };
104	   104	  const cur = await db.cyrusStorageAccount.findUnique({ where: { userId: user.id } });
105	   105	  if (cur?.addonMethod === "card" && cur.addonStatus === "active") return { state: "invalid", chargedCents: 0, error: "Your storage is paid by card: change it from the card subscription (cancel, then buy the new amount)." };
106	   106	  const from = effectiveAddonGb(cur, now);
107	   107	  const plan = planChange({ fromGb: from, toGb: gb, periodStart: cur?.addonPeriodStart ?? null, periodEnd: cur?.addonPeriodEnd ?? null, now, rule: cfg.rule, table: cfg.table });
108	   108	  if (plan.kind === "same") {
109	   109	    if (cur?.addonNextGb !== null && cur?.addonNextGb !== undefined) { await db.cyrusStorageAccount.update({ where: { userId: user.id }, data: { addonNextGb: null } }); return { state: "scheduled", chargedCents: 0, effective: "now" }; }
110	   110	    return { state: "unchanged", chargedCents: 0 };
111	   111	  }
112	   112	  if (plan.kind === "decrease") {
113	   113	    await db.cyrusStorageAccount.update({ where: { userId: user.id }, data: { addonNextGb: gb } });
114	   114	    await getHost().audit.record(user.id, "cyrus.storage.addon.decrease", `${from} -> ${gb} GB at period end`).catch(() => undefined);
115	   115	    return { state: "scheduled", chargedCents: 0, effective: "period_end" };
116	   116	  }
117	   117	  const change: StorageChange = plan.kind === "new" ? "purchase" : "increase";
118	   118	  const ref = storageRef(user.id, gb, key);
119	   119	  if (locks.has(ref)) return { state: "in_progress", chargedCents: 0 };
120	   120	  locks.add(ref);
121	   121	  try {
122	   122	    if (await db.cyrusStorageCharge.findUnique({ where: { idemKey: ref }, select: { id: true } })) return { state: "active", chargedCents: 0 };
123	   123	    const periodEnd = change === "purchase" ? addMonth(now) : cur?.addonPeriodEnd ?? addMonth(now);
124	   124	    const env = storageEnvelope("purchase.completed", user.id, { idemKey: ref, method: "wallet", gb, gbFrom: from, change, cents: plan.chargeCents, periodEnd }, now);
125	   125	    if (plan.chargeCents > 0) {
126	   126	      const c = await wallet.charge({ userId: user.id, cents: plan.chargeCents, description: `Cyrus storage +${gb} GB monthly${change === "increase" ? " (upgrade, prorated)" : ""}`, reference: ref });
127	   127	      if (!c.ok) return { state: c.error === "insufficient_funds" ? "insufficient_funds" : "invalid", chargedCents: 0, error: c.error === "insufficient_funds" ? "Not enough in your wallet. Add funds at Nxeon or pay by card." : "Couldn't charge your wallet." };
128	   128	    }
129	   129	    try {
130	   130	      const s = await deliverStorage(env);
131	   131	      return { state: s === "applied" ? "active" : "pending", chargedCents: plan.chargeCents, effective: "now" };
132	   132	    } catch (err) {
133	   133	      console.error("[cyrus-storage] apply failed after wallet charge", ref, (err as Error).message);
134	   134	      if (plan.chargeCents <= 0) return { state: "failed", chargedCents: 0, error: "We couldn't change your storage. Nothing was charged." };
135	   135	      try {
136	   136	        await wallet.refund({ userId: user.id, cents: plan.chargeCents, description: "Refund: Cyrus storage not added", reference: `${ref}:refund` });
137	   137	        return { state: "failed", chargedCents: 0, error: "We couldn't add your storage, so your wallet was refunded." };
138	   138	      } catch {
139	   139	        return { state: "pending", chargedCents: plan.chargeCents, error: "Your storage is on the way. If it doesn't appear in a few minutes, contact support." };
140	   140	      }
141	   141	    }
142	   142	  } finally {
143	   143	    locks.delete(ref);
144	   144	  }
145	   145	}
