162	   162	/** Refund the wallet charge of the current period (staff or the customer's refund window): money back, GB back. */
163	   163	export async function refundStorageCharge(userId: string, idemKey: string, cents?: number): Promise<{ ok: boolean; cents: number }> {
164	   164	  const row = await db.cyrusStorageCharge.findUnique({ where: { idemKey } });
165	   165	  const w = getHost().billing.wallet;
166	   166	  if (!row || row.userId !== userId || row.method !== "wallet" || !w) return { ok: false, cents: 0 };
167	   167	  const amount = Math.min(row.cents - row.refundedCents, cents ?? row.cents - row.refundedCents);
168	   168	  if (amount <= 0) return { ok: false, cents: 0 };
169	   169	  const r = await applyStorageEvent(storageEnvelope("purchase.refunded", userId, { idemKey, method: "wallet", gb: row.gbTo, gbFrom: row.gbFrom, change: row.kind as StorageChange, cents: row.cents, periodEnd: row.periodEnd, refundedCents: row.refundedCents + amount }));
170	   170	  if (!r.applied) return { ok: false, cents: 0 };
171	   171	  await w.refund({ userId, cents: amount, description: "Refund: Cyrus storage", reference: `${idemKey}:refund:${row.refundedCents + amount}` });
