175	   175	/** Sweep: renew wallet add-ons whose period ended (once per period, idempotent key), apply scheduled decreases and
176	   176	 *  cancels, retry a failed renewal once a day for 7 days, then cancel. Card add-ons renew on Stripe's side. */
177	   177	export async function storageRenewalSweep(now = new Date(), batch = 50): Promise<{ renewed: number; lapsed: number; failed: number }> {
178	   178	  if (!storageAddonsEnabled()) return { renewed: 0, lapsed: 0, failed: 0 };
179	   179	  const wallet = getHost().billing.wallet;
180	   180	  const cfg = await loadStorageConfig();
181	   181	  const due = await db.cyrusStorageAccount.findMany({ where: { addonMethod: "wallet", addonStatus: { in: ["active", "past_due"] }, addonPeriodEnd: { lte: now } }, take: batch });
182	   182	  let renewed = 0, lapsed = 0, failed = 0;
183	   183	  for (const r of due) {
184	   184	    const end = r.addonPeriodEnd!;
185	   185	    const next = r.addonNextGb ?? r.addonGb;
186	   186	    const lapse = async (status: string) => { await db.cyrusStorageAccount.update({ where: { userId: r.userId }, data: { addonStatus: status, addonGb: status === "canceled" ? 0 : r.addonGb, addonNextGb: null, dirtyAt: now } }); await recomputeStorage(r.userId).catch(() => undefined); lapsed++; };
187	   187	    if (next <= 0) { await lapse("canceled"); continue; }
188	   188	    if (r.addonStatus === "past_due" && (now.getTime() - end.getTime() > 7 * DAY)) { await lapse("canceled"); continue; }
189	   189	    if (r.addonStatus === "past_due" && now.getTime() - r.updatedAt.getTime() < DAY) continue;
190	   190	    if (!wallet) continue;
191	   191	    const ref = storageRef(r.userId, next, `renew_${end.getTime()}`);
192	   192	    const cents = storagePriceCents(next, cfg.rule, cfg.table);
193	   193	    let newEnd = addMonth(end); if (newEnd.getTime() <= now.getTime()) newEnd = addMonth(now);
194	   194	    const c = await wallet.charge({ userId: r.userId, cents, description: `Cyrus storage +${next} GB monthly (renewal)`, reference: ref });
195	   195	    if (!c.ok) { await db.cyrusStorageAccount.update({ where: { userId: r.userId }, data: { addonStatus: "past_due", dirtyAt: now } }); await recomputeStorage(r.userId).catch(() => undefined); failed++; continue; }
196	   196	    await deliverStorage(storageEnvelope("purchase.completed", r.userId, { idemKey: ref, method: "wallet", gb: next, gbFrom: r.addonGb, change: "renewal", cents, periodEnd: newEnd }, now));
197	   197	    renewed++;
198	   198	  }
199	   199	  return { renewed, lapsed, failed };
200	   200	}
