202	   202	/** Reconcile: a referenced wallet charge without a charge row (lost apply, dead webhook) is applied once, from its reference. */
203	   203	export async function reconcileStorageCharges(o: { userId?: string; sinceMs?: number } = {}, now = new Date()): Promise<{ checked: number; applied: number }> {
204	   204	  const w = getHost().billing.wallet;
205	   205	  if (!storageAddonsEnabled() || !w?.findByReference) return { checked: 0, applied: 0 };
206	   206	  const moves = await w.findByReference({ userId: o.userId, prefix: "cst:", sinceMs: o.sinceMs ?? now.getTime() - 7 * DAY });
207	   207	  const refunded = new Set(moves.filter((m) => m.cents > 0 && m.reference.includes(":refund")).map((m) => m.reference.split(":refund")[0]));
208	   208	  let checked = 0, applied = 0;
209	   209	  for (const m of moves) {
210	   210	    const p = parseStorageRef(m.reference);
211	   211	    if (m.cents >= 0 || !p || refunded.has(m.reference) || locks.has(m.reference) || now.getTime() - m.at.getTime() < 10 * 60_000) continue;
212	   212	    checked++;
213	   213	    if (await db.cyrusStorageCharge.findUnique({ where: { idemKey: m.reference }, select: { id: true } })) continue;
214	   214	    const cur = await db.cyrusStorageAccount.findUnique({ where: { userId: m.userId } });
215	   215	    const change: StorageChange = p.key.startsWith("renew_") ? "renewal" : effectiveAddonGb(cur, m.at) > 0 ? "increase" : "purchase";
216	   216	    if ((await applyStorageEvent(storageEnvelope("purchase.completed", m.userId, { idemKey: m.reference, method: "wallet", gb: p.gb, gbFrom: cur?.addonGb ?? 0, change, cents: -m.cents, periodEnd: change === "increase" ? cur?.addonPeriodEnd ?? null : addMonth(m.at) }, m.at))).applied) applied++;
217	   217	  }
218	   218	  return { checked, applied };
219	   219	}
