245	   245	/** Card add-on events (call from the Stripe webhook BEFORE the plan handler). true = it was a storage event.
246	   246	 *  invoice.paid -> purchase / renewal (idemKey stripe:<invoice>); subscription deleted -> lapse; charge.refunded -> refund. */
247	   247	export async function handleStorageStripeEvent(event: Stripe.Event): Promise<boolean> {
248	   248	  const s = getHost().billing.stripe;
249	   249	  if (!storageAddonsEnabled() || !s?.configured()) return false;
250	   250	  const obj = event.data.object as unknown as Record<string, unknown> & { id: string };
251	   251	  const subOf = async (id: string | null) => (id ? s.client().subscriptions.retrieve(id, {}, s.requestOptions).catch(() => null) : null);
252	   252	  if (event.type === "invoice.paid" || event.type === "invoice.payment_succeeded") {
253	   253	    const inv = await s.client().invoices.retrieve(obj.id, {}, s.requestOptions);
254	   254	    const subId = (inv as unknown as { subscription?: string | { id: string } | null; parent?: { subscription_details?: { subscription?: string | { id: string } } } }).subscription ?? (inv as unknown as { parent?: { subscription_details?: { subscription?: string | { id: string } } } }).parent?.subscription_details?.subscription ?? null;
255	   255	    const sid = typeof subId === "string" ? subId : subId?.id ?? null;
256	   256	    const sub = await subOf(sid);
257	   257	    const m = subMeta(sub);
258	   258	    if (!m || !sid || inv.status !== "paid") return !!m;
259	   259	    const cur = await db.cyrusStorageAccount.findUnique({ where: { userId: m.userId } });
260	   260	    const line = inv.lines?.data?.[0] as unknown as { period?: { end?: number } } | undefined;
261	   261	    const periodEnd = line?.period?.end ? new Date(line.period.end * 1000) : null;
262	   262	    await applyStorageEvent(storageEnvelope("purchase.completed", m.userId, { idemKey: `stripe:${inv.id}`, method: "card", gb: m.gb, gbFrom: cur?.addonGb ?? 0, change: cur?.addonSubRef === sid ? "renewal" : "purchase", cents: inv.amount_paid ?? 0, periodEnd, sourceRef: sid }));
263	   263	    await db.cyrusStorageAccount.update({ where: { userId: m.userId }, data: { addonSubRef: sid } }).catch(() => undefined);
264	   264	    return true;
265	   265	  }
266	   266	  if (event.type === "customer.subscription.deleted" || event.type === "customer.subscription.updated") {
267	   267	    const sub = await subOf(obj.id);
268	   268	    const m = subMeta(sub);
269	   269	    if (!m) return false;
270	   270	    if (event.type === "customer.subscription.deleted" || sub?.status === "canceled" || sub?.status === "unpaid") {
271	   271	      await db.cyrusStorageAccount.updateMany({ where: { userId: m.userId, addonSubRef: obj.id }, data: { addonStatus: "canceled", addonGb: 0, addonNextGb: null, dirtyAt: new Date() } });
272	   272	      await recomputeStorage(m.userId).catch(() => undefined);
273	   273	    } else {
274	   274	      await db.cyrusStorageAccount.updateMany({ where: { userId: m.userId, addonSubRef: obj.id }, data: { addonNextGb: sub?.cancel_at_period_end ? 0 : null } });
275	   275	    }
276	   276	    return true;
277	   277	  }
278	   278	  if (event.type === "charge.refunded") {
279	   279	    const ch = await s.client().charges.retrieve(obj.id, { expand: ["invoice"] }, s.requestOptions).catch(() => null);
280	   280	    const invId = (ch as unknown as { invoice?: string | { id: string } | null } | null)?.invoice;
281	   281	    const iid = typeof invId === "string" ? invId : invId?.id ?? null;
282	   282	    if (!ch || !iid) return false;
283	   283	    const row = await db.cyrusStorageCharge.findUnique({ where: { idemKey: `stripe:${iid}` } });
284	   284	    if (!row) return false;
285	   285	    await applyStorageEvent(storageEnvelope("purchase.refunded", row.userId, { idemKey: row.idemKey, method: "card", gb: row.gbTo, gbFrom: row.gbFrom, change: row.kind as StorageChange, cents: row.cents, periodEnd: row.periodEnd, refundedCents: ch.amount_refunded ?? 0 }));
286	   286	    return true;
287	   287	  }
288	   288	  return false;
289	   289	}
