291	   291	/** Entitlement mirror (lib/cyrus/tokens/entitlement.ts): a wallet storage charge Nxeon reports. Applies it once if this
292	   292	 *  side never did (same idemKey), and records a refund once. */
293	   293	export async function applyMirroredStorageCharge(userId: string, s: { idemKey: string; gb: number; cents: number; at: string; refundedCents: number }, now = new Date()): Promise<void> {
294	   294	  const p = parseStorageRef(s.idemKey);
295	   295	  if (!p || p.userId !== userId) return;
296	   296	  let row = await db.cyrusStorageCharge.findUnique({ where: { idemKey: s.idemKey } });
297	   297	  if (!row) {
298	   298	    if (s.refundedCents >= s.cents && s.cents > 0) return; // refunded before it was ever applied (the compensating refund)
299	   299	    const at = new Date(s.at);
300	   300	    const cur = await db.cyrusStorageAccount.findUnique({ where: { userId } });
301	   301	    const change: StorageChange = p.key.startsWith("renew_") ? "renewal" : effectiveAddonGb(cur, at) > 0 ? "increase" : "purchase";
302	   302	    await applyStorageEvent(storageEnvelope("purchase.completed", userId, { idemKey: s.idemKey, method: "wallet", gb: p.gb, gbFrom: cur?.addonGb ?? 0, change, cents: s.cents, periodEnd: change === "increase" ? cur?.addonPeriodEnd ?? null : addMonth(at) }, at));
303	   303	    row = await db.cyrusStorageCharge.findUnique({ where: { idemKey: s.idemKey } });
304	   304	  }
305	   305	  if (row && s.refundedCents > row.refundedCents)
306	   306	    await applyStorageEvent(storageEnvelope("purchase.refunded", userId, { idemKey: s.idemKey, method: "wallet", gb: row.gbTo, gbFrom: row.gbFrom, change: row.kind as StorageChange, cents: row.cents, periodEnd: row.periodEnd, refundedCents: s.refundedCents }, now));
307	   307	}
308	   308	// Cyrus storage (r51): plan quotas, the BUY-MORE-STORAGE price table and the pricing rule. PURE + client-safe (the slider
309	   309	// renders the same numbers the server charges). Every number is a PLACEHOLDER until the owner confirms it (OWNER-ACTIONS
310	   310	// "r51 storage"); a Setting row overrides each default, and a blank or bad value falls back to the default, never to 0.
311	   311	//
312	   312	// Units: 1 GB = 2^30 bytes (binary, what `df -h` shows). Money: integer cents, monthly.
313	   313	//
314	   314	// The owner's per-GB rates (1 GB $0.85, 5 GB $0.75, 25 GB $0.60, 50 GB $0.30, 100 GB $0.20) read literally have a CLIFF
315	   315	// (49 GB = $29.40 but 50 GB = $15.00). Rule "capped" (DEFAULT, the stated assumption):
316	   316	//   rate(n)  = the rate of the highest breakpoint <= n          (bands 1-4, 5-24, 25-49, 50-99, 100+)
317	   317	//   cost(n)  = min( rate(n) * n , min over breakpoints b > n of rate(b) * b )
318	   318	// so fewer GB never cost more than the next breakpoint. Alternatives, one setting away (cyrus_storage_pricing_rule):
319	   319	//   "literal"    rate(n) * n, the cliff as written;
320	   320	//   "graduated"  each GB priced at its own band's rate (like tax brackets): no cliff, no flat stretches, dearer at volume.
321	   321	export const GB = 1024 ** 3;
322	   322	
323	   323	export type PriceBand = { fromGb: number; centsPerGb: number };
324	   324	export const PRICING_RULES = ["capped", "literal", "graduated"] as const;
325	   325	export type PricingRule = (typeof PRICING_RULES)[number];
326	   326	
327	   327	/** The owner's numbers (2026-10-11), monthly. */
328	   328	export const DEFAULT_PRICE_TABLE: PriceBand[] = [
329	   329	  { fromGb: 1, centsPerGb: 85 },
330	   330	  { fromGb: 5, centsPerGb: 75 },
331	   331	  { fromGb: 25, centsPerGb: 60 },
332	   332	  { fromGb: 50, centsPerGb: 30 },
333	   333	  { fromGb: 100, centsPerGb: 20 },
334	   334	];
335	   335	
336	   336	/** Validate an admin-edited table: 1-10 bands, the first from 1 GB, strictly ascending whole GB, 1..100000 cents per GB. */
337	   337	export function validatePriceTable(raw: unknown): { ok: true; table: PriceBand[] } | { ok: false; error: string } {
338	   338	  let v = raw;
339	   339	  if (typeof v === "string") { try { v = JSON.parse(v); } catch { return { ok: false, error: "Not valid JSON." }; } }
340	   340	  if (!Array.isArray(v) || v.length < 1 || v.length > 10) return { ok: false, error: "Use a list of 1 to 10 bands." };
341	   341	  const out: PriceBand[] = [];
342	   342	  for (const [i, b] of v.entries()) {
343	   343	    const fromGb = Number((b as PriceBand)?.fromGb), cents = Number((b as PriceBand)?.centsPerGb);
344	   344	    if (!Number.isInteger(fromGb) || fromGb < 1 || fromGb > 100_000) return { ok: false, error: `Band ${i + 1}: fromGb must be a whole number of GB.` };
345	   345	    if (!Number.isInteger(cents) || cents < 1 || cents > 100_000) return { ok: false, error: `Band ${i + 1}: centsPerGb must be 1 to 100000 cents.` };
346	   346	    if (i === 0 && fromGb !== 1) return { ok: false, error: "The first band must start at 1 GB." };
347	   347	    if (i > 0 && fromGb <= out[i - 1].fromGb) return { ok: false, error: "Bands must go up in GB." };
348	   348	    out.push({ fromGb, centsPerGb: cents });
349	   349	  }
350	   350	  return { ok: true, table: out };
351	   351	}
352	   352	
353	   353	/** Cents per GB of the band n falls in (n >= 1). */
354	   354	export function rateFor(gb: number, table: PriceBand[] = DEFAULT_PRICE_TABLE): number {
355	   355	  let r = table[0].centsPerGb;
356	   356	  for (const b of table) if (gb >= b.fromGb) r = b.centsPerGb;
357	   357	  return r;
358	   358	}
359	   359	
360	   360	export const literalCents = (gb: number, table: PriceBand[] = DEFAULT_PRICE_TABLE) => (gb >= 1 ? rateFor(gb, table) * gb : 0);
361	   361	
362	   362	export function cappedCents(gb: number, table: PriceBand[] = DEFAULT_PRICE_TABLE): number {
363	   363	  if (gb < 1) return 0;
364	   364	  let best = literalCents(gb, table);
365	   365	  for (const b of table) if (b.fromGb > gb) best = Math.min(best, b.centsPerGb * b.fromGb);
366	   366	  return best;
367	   367	}
368	   368	
369	   369	export function graduatedCents(gb: number, table: PriceBand[] = DEFAULT_PRICE_TABLE): number {
370	   370	  let total = 0;
371	   371	  for (const [i, b] of table.entries()) {
372	   372	    const end = table[i + 1]?.fromGb ?? Infinity; // band covers [fromGb, end)
373	   373	    const n = Math.max(0, Math.min(gb + 1, end) - b.fromGb);
374	   374	    total += n * b.centsPerGb;
375	   375	  }
376	   376	  return total;
377	   377	}
378	   378	
379	   379	/** THE monthly price of `gb` extra GB under the configured rule (0 GB = 0). */
380	   380	export function storagePriceCents(gb: number, rule: PricingRule = "capped", table: PriceBand[] = DEFAULT_PRICE_TABLE): number {
381	   381	  const n = Math.floor(gb);
382	   382	  if (!(n >= 1)) return 0;
383	   383	  return rule === "literal" ? literalCents(n, table) : rule === "graduated" ? graduatedCents(n, table) : cappedCents(n, table);
384	   384	}
385	   385	
386	   386	/** The most GB the same monthly price buys (>= gb): under "capped" 20 GB costs what 50 GB costs, so the slider says so. */
387	   387	export function samePriceUpTo(gb: number, rule: PricingRule = "capped", table: PriceBand[] = DEFAULT_PRICE_TABLE, maxGb = 100_000): number {
388	   388	  const n = Math.floor(gb), p = storagePriceCents(n, rule, table);
389	   389	  let best = n;
390	   390	  for (let g = n + 1; g <= maxGb && storagePriceCents(g, rule, table) <= p; g++) best = g;
391	   391	  return best;
392	   392	}
393	   393	
394	   394	export type PriceRow = { gb: number; cents: number; centsPerGb: number; literalCents: number; savedCents: number };
395	   395	/** The table the owner reviews (tests print it; the slider charts it). */
396	   396	export function priceRows(points: number[], rule: PricingRule = "capped", table: PriceBand[] = DEFAULT_PRICE_TABLE): PriceRow[] {
397	   397	  return points.map((gb) => {
398	   398	    const cents = storagePriceCents(gb, rule, table), lit = literalCents(gb, table);
399	   399	    return { gb, cents, centsPerGb: Math.round((cents / gb) * 100) / 100, literalCents: lit, savedCents: lit - cents };
400	   400	  });
401	   401	}
402	   402	export const REVIEW_POINTS = [1, 2, 4, 5, 10, 19, 20, 24, 25, 30, 40, 49, 50, 60, 66, 67, 80, 99, 100, 150, 200, 500];
403	   403	
404	   404	export const fmtCents = (c: number) => `$${(c / 100).toFixed(2)}`;
405	   405	export function fmtBytes(b: number): string {
406	   406	  const n = Math.max(0, b);
407	   407	  if (n >= GB) return `${(n / GB).toFixed(n >= 100 * GB ? 0 : n >= 10 * GB ? 1 : 2)} GB`;
408	   408	  if (n >= 1024 ** 2) return `${(n / 1024 ** 2).toFixed(n >= 100 * 1024 ** 2 ? 0 : 1)} MB`;
409	   409	  if (n >= 1024) return `${Math.round(n / 1024)} KB`;
410	   410	  return `${n} B`;
411	   411	}
