413	   413	// ---------------------------------------------------------------------------
414	   414	// Proration of a mid-period change (monthly add-on)
415	   415	// ---------------------------------------------------------------------------
416	   416	
417	   417	export type ChangePlan =
418	   418	  | { kind: "new"; chargeCents: number; effective: "now" }
419	   419	  | { kind: "increase"; chargeCents: number; effective: "now" }
420	   420	  | { kind: "decrease"; chargeCents: 0; effective: "period_end" }
421	   421	  | { kind: "same"; chargeCents: 0; effective: "now" };
422	   422	
423	   423	/** Increase = the price difference for the rest of the period, charged now (rounded up to the cent); the next renewal
424	   424	 *  charges the full new price. Decrease (or cancel, toGb 0) = nothing back mid-period, the smaller amount starts at the
425	   425	 *  next renewal (the customer keeps what they paid for until then). */
426	   426	export function planChange(a: { fromGb: number; toGb: number; periodStart: Date | null; periodEnd: Date | null; now: Date; rule?: PricingRule; table?: PriceBand[] }): ChangePlan {
427	   427	  const price = (g: number) => storagePriceCents(g, a.rule, a.table);
428	   428	  if (a.fromGb <= 0 || !a.periodEnd || !a.periodStart || a.periodEnd.getTime() <= a.now.getTime()) return a.toGb > 0 ? { kind: "new", chargeCents: price(a.toGb), effective: "now" } : { kind: "same", chargeCents: 0, effective: "now" };
429	   429	  if (a.toGb === a.fromGb) return { kind: "same", chargeCents: 0, effective: "now" };
430	   430	  if (a.toGb < a.fromGb) return { kind: "decrease", chargeCents: 0, effective: "period_end" };
431	   431	  const total = a.periodEnd.getTime() - a.periodStart.getTime();
432	   432	  const left = Math.max(0, Math.min(total, a.periodEnd.getTime() - a.now.getTime()));
433	   433	  const diff = Math.max(0, price(a.toGb) - price(a.fromGb));
434	   434	  return { kind: "increase", chargeCents: total > 0 ? Math.ceil((diff * left) / total) : diff, effective: "now" };
435	   435	}
436	   436	
437	   437	/** One calendar month later (end of month clamps: Jan 31 -> Feb 28/29). */
438	   438	export function addMonth(d: Date): Date {
439	   439	  const y = d.getUTCFullYear(), m = d.getUTCMonth(), day = d.getUTCDate();
440	   440	  const last = new Date(Date.UTC(y, m + 2, 0)).getUTCDate();
441	   441	  return new Date(Date.UTC(y, m + 1, Math.min(day, last), d.getUTCHours(), d.getUTCMinutes(), d.getUTCSeconds(), d.getUTCMilliseconds()));
442	   442	}
443	   443	// Cyrus storage service (r51), SERVER ONLY: recompute (full, per account), incremental updates, the SERVER-SIDE write gate
444	   444	// (fail CLOSED), the sweep and the daily snapshot. Off (CYRUS_STORAGE unset) = every function here is a no-op and every
445	   445	// write is allowed, exactly as before. HOST SEAM: Cyrus tables via cyrusDb only.
446	   446	import { cyrusDb as db } from "../db";
447	   447	import { tierOf } from "../tokens/access";
448	   448	import type { TokenTier } from "../tokens/config";
449	   449	import { nextOverState, rollup, storageFullMessage, storageWriteDecision, STORAGE_FULL_CODE, type StorageBreakdown, type WriteKind } from "./accounting";
450	   450	import { collectItems, type StorageSources } from "./collect";
451	   451	import { prismaStorageSources } from "./collect-db";
452	   452	import { loadStorageConfig, quotaBytes, storageEnabled, type StorageConfig } from "./config";
453	   453	
454	   454	const DAY = 86_400_000;
455	   455	export const STALE_MS = DAY;
456	   456	
457	   457	export type StorageDeps = { sources: StorageSources; tier: (userId: string) => Promise<TokenTier>; config: () => Promise<StorageConfig>; now: () => Date };
458	   458	let override: Partial<StorageDeps> | null = null;
459	   459	export function setStorageDepsForTests(d: Partial<StorageDeps> | null) { override = d; }
460	   460	const deps = (): StorageDeps => ({ sources: prismaStorageSources(), tier: (u) => tierOf(u), config: () => loadStorageConfig(), now: () => new Date(), ...(override ?? {}) });
461	   461	
462	   462	type Row = NonNullable<Awaited<ReturnType<typeof db.cyrusStorageAccount.findUnique>>>;
463	   463	const N = (b: bigint | number | null | undefined) => Number(b ?? 0);
464	   464	
465	   465	/** The add-on GB in force now: an active add-on whose paid period has not ended. */
466	   466	export function effectiveAddonGb(row: Pick<Row, "addonGb" | "addonStatus" | "addonPeriodEnd"> | null, now: Date): number {
467	   467	  if (!row || row.addonStatus !== "active" || !row.addonPeriodEnd || row.addonPeriodEnd.getTime() <= now.getTime()) return 0;
468	   468	  return Math.max(0, row.addonGb);
469	   469	}
470	   470	
471	   471	export type AccountStorage = {
472	   472	  userId: string; tier: TokenTier; usedBytes: number; pendingBytes: number; quotaBytes: number; planGb: number; addonGb: number;
473	   473	  breakdown: StorageBreakdown | null; computedAt: Date | null; overSince: Date | null; graceUntil: Date | null;
474	   474	  addon: { gb: number; nextGb: number | null; status: string; method: string | null; periodStart: Date | null; periodEnd: Date | null };
475	   475	};
476	   476	function view(row: Row, tier: TokenTier, cfg: StorageConfig, now: Date): AccountStorage {
477	   477	  const addonGb = effectiveAddonGb(row, now);
478	   478	  return {
479	   479	    userId: row.userId, tier, usedBytes: N(row.usedBytes), pendingBytes: N(row.pendingBytes), quotaBytes: quotaBytes(tier, addonGb, cfg), planGb: cfg.quotaGb[tier], addonGb,
480	   480	    breakdown: (row.breakdown as StorageBreakdown | null) ?? null, computedAt: row.computedAt, overSince: row.overSince, graceUntil: row.graceUntil,
481	   481	    addon: { gb: row.addonGb, nextGb: row.addonNextGb, status: row.addonStatus, method: row.addonMethod, periodStart: row.addonPeriodStart, periodEnd: row.addonPeriodEnd },
482	   482	  };
483	   483	}
484	   484	
485	   485	/** Full recompute of one account: collect -> dedupe/rollup -> quota -> over-quota state -> store. */
486	   486	export async function recomputeStorage(userId: string): Promise<AccountStorage> {
487	   487	  const d = deps();
488	   488	  const now = d.now();
489	   489	  const before = await db.cyrusStorageAccount.findUnique({ where: { userId } });
490	   490	  const pendingSeen = N(before?.pendingBytes);
491	   491	  const [items, tier, cfg] = await Promise.all([collectItems(userId, d.sources), d.tier(userId), d.config()]);
492	   492	  const b = rollup(items);
493	   493	  const quota = quotaBytes(tier, effectiveAddonGb(before, now), cfg);
494	   494	  const over = nextOverState({ usedBytes: b.totalBytes, quotaBytes: quota, prevQuotaBytes: before ? N(before.quotaBytes) : null, prev: before ? { overSince: before.overSince, graceUntil: before.graceUntil } : null, graceDays: cfg.graceDays, now });
495	   495	  const data = { usedBytes: BigInt(b.totalBytes), quotaBytes: BigInt(quota), breakdown: b as unknown as object, computedAt: now, dirtyAt: null, overSince: over.overSince, graceUntil: over.graceUntil };
496	   496	  const row = await db.cyrusStorageAccount.upsert({
497	   497	    where: { userId },
498	   498	    create: { userId, ...data, pendingBytes: BigInt(0) },
499	   499	    // writes that landed while we collected stay pending (they may or may not be in this measurement: never under-count)
500	   500	    update: { ...data, pendingBytes: { decrement: BigInt(pendingSeen) } },
501	   501	  });
502	   502	  if (N(row.pendingBytes) < 0) await db.cyrusStorageAccount.update({ where: { userId }, data: { pendingBytes: BigInt(0) } });
503	   503	  return view({ ...row, pendingBytes: BigInt(Math.max(0, N(row.pendingBytes))) }, tier, cfg, now);
504	   504	}
505	   505	
506	   506	/** The account's storage as stored, recomputed when missing, stale (24 h) or when its quota went down since. */
507	   507	export async function accountStorage(userId: string): Promise<AccountStorage> {
508	   508	  const d = deps();
509	   509	  const now = d.now();
510	   510	  const row = await db.cyrusStorageAccount.findUnique({ where: { userId } });
511	   511	  if (!row || !row.computedAt || now.getTime() - row.computedAt.getTime() > STALE_MS) return recomputeStorage(userId); // dirty rows: pending bytes already count; the sweep recomputes them
512	   512	  const [tier, cfg] = await Promise.all([d.tier(userId), d.config()]);
513	   513	  const live = quotaBytes(tier, effectiveAddonGb(row, now), cfg);
514	   514	  if (live < N(row.quotaBytes) && N(row.usedBytes) + N(row.pendingBytes) > live) return recomputeStorage(userId); // a drop: start the grace
515	   515	  return view(row, tier, cfg, now);
516	   516	}
