518	   518	export type StorageGate = { ok: true; grace: boolean } | { ok: false; status: 507 | 503; code: string; error: string; usedBytes?: number; quotaBytes?: number };
519	   519	
520	   520	/** THE server-side gate for new builds, uploads, asset saves, library contributions, pack versions and imports.
521	   521	 *  Off = allowed. On = fail CLOSED: if usage cannot be read the write is refused. Never call it for installs,
522	   522	 *  downloads, exports or deletes. */
523	   523	export async function checkStorageWrite(userId: string, addBytes: number, what: WriteKind): Promise<StorageGate> {
524	   524	  if (!storageEnabled()) return { ok: true, grace: false };
525	   525	  try {
526	   526	    const s = await accountStorage(userId);
527	   527	    const d = storageWriteDecision({ usedBytes: s.usedBytes, pendingBytes: s.pendingBytes, quotaBytes: s.quotaBytes, addBytes: Math.max(0, Math.floor(addBytes)), graceUntil: s.graceUntil, now: deps().now() });
528	   528	    if (d.ok) return d;
529	   529	    return { ok: false, status: 507, code: STORAGE_FULL_CODE, error: storageFullMessage(what), usedBytes: d.usedBytes, quotaBytes: d.quotaBytes };
530	   530	  } catch (e) {
531	   531	    console.error("[cyrus-storage] gate failed closed", userId, (e as Error).message);
532	   532	    return { ok: false, status: 503, code: "storage_unknown", error: "We couldn't check your Cyrus storage just now, so nothing was started or charged. Please try again in a minute." };
533	   533	  }
534	   534	}
