536	   536	/** Incremental update after a write: the bytes count at once (pending), the next sweep recomputes exactly. Best effort. */
537	   537	export async function noteStorageWrite(userId: string, bytes: number): Promise<void> {
538	   538	  if (!storageEnabled() || !userId) return;
539	   539	  const add = BigInt(Math.max(0, Math.floor(bytes)));
540	   540	  const now = deps().now();
541	   541	  await db.cyrusStorageAccount.upsert({ where: { userId }, create: { userId, pendingBytes: add, dirtyAt: now }, update: { pendingBytes: { increment: add }, dirtyAt: now } })
542	   542	    .catch((e) => console.error("[cyrus-storage] note write", (e as Error).message));
543	   543	}
544	   544	/** Something was removed or changed size: recompute on the next sweep. */
545	   545	export async function markStorageDirty(userId: string): Promise<void> { await noteStorageWrite(userId, 0); }
546	   546	
547	   547	const dayKey = (d: Date) => d.toISOString().slice(0, 10);
548	   548	
549	   549	/** Sweep (worker, every 5 min): recompute dirty and stale accounts (batch), then today's snapshot once. */
550	   550	export async function storageSweep(batch = 50): Promise<{ recomputed: number; snapshot: boolean }> {
551	   551	  if (!storageEnabled()) return { recomputed: 0, snapshot: false };
552	   552	  const now = deps().now();
553	   553	  const rows = await db.cyrusStorageAccount.findMany({ where: { OR: [{ dirtyAt: { not: null } }, { computedAt: null }, { computedAt: { lt: new Date(now.getTime() - STALE_MS) } }] }, select: { userId: true }, orderBy: { dirtyAt: "asc" }, take: batch });
554	   554	  let recomputed = 0;
555	   555	  for (const r of rows) { try { await recomputeStorage(r.userId); recomputed++; } catch (e) { console.error("[cyrus-storage] recompute", r.userId, (e as Error).message); } }
556	   556	  return { recomputed, snapshot: await takeSnapshot(now) };
557	   557	}
558	   558	
559	   559	export async function takeSnapshot(now: Date): Promise<boolean> {
560	   560	  const day = dayKey(now);
561	   561	  if (await db.cyrusStorageSnapshot.findUnique({ where: { day }, select: { day: true } })) return false;
562	   562	  const agg = await db.cyrusStorageAccount.aggregate({ _sum: { usedBytes: true, pendingBytes: true }, _count: { userId: true } });
563	   563	  const over = await db.cyrusStorageAccount.count({ where: { overSince: { not: null } } });
564	   564	  const addons = await db.cyrusStorageAccount.aggregate({ where: { addonStatus: "active" }, _sum: { addonGb: true }, _count: { userId: true } });
565	   565	  await db.cyrusStorageSnapshot.create({ data: { day, totalBytes: BigInt(N(agg._sum.usedBytes) + N(agg._sum.pendingBytes)), accounts: agg._count.userId, detail: { over, addonAccounts: addons._count.userId, addonGb: addons._sum.addonGb ?? 0 } } }).catch(() => undefined);
566	   566	  return true;
567	   567	}
